const fmt = d => d.toISOString().split('.')[0] + '.000Z';

const now = new Date();
const to = fmt(now);

// 24 hours ago (86,400,000 ms)
const fromDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const from = fmt(fromDate);

return {
  from,
  to,
  now: to
};

const data = items[0].json;

let ticker = "UNKNOWN";
if (data.quotes && data.quotes.length > 0) {
  ticker = data.quotes[0].symbol.toUpperCase();
}

return [{ json: { ticker } }];

// n8n Code node: Output Telegram
// MODE: Run Once for Each Item
//
// FIXES:
// - Pull deterministic context from Compute Trend & Confidence + Compare Candidates (avoid "n/a")
// - Prevent AI from overriding workflow truth (only explanatory allowlist)
// - If workflow did not provide option_decision, accept AI option_decision (still subject to gates)
// - If AI was overridden to WAIT, prepend WHY WAIT (time gate / liquidity / missing candidate_pass / RR extreme guardrail / missing levels)

function isPlainObject(x) {
  return x != null && typeof x === "object" && !Array.isArray(x);
}

function safeNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string") {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function stripCodeFences(s) {
  if (typeof s !== "string") return s;
  let t = s.trim();
  t = t.replace(/^```(?:json)?\s*/i, "");
  t = t.replace(/\s*```$/i, "");
  return t.trim();
}

function parseMaybeJson(x) {
  if (x == null) return null;
  if (typeof x === "object") return x;
  if (typeof x !== "string") return null;
  const t = stripCodeFences(x);
  if (!t) return null;
  try {
    return JSON.parse(t);
  } catch {
    return null;
  }
}

function mergePreferDefined(target, source) {
  if (!isPlainObject(source)) return target;
  for (const [k, v] of Object.entries(source)) {
    if (v === undefined || v === null) continue;
    if (isPlainObject(v) && isPlainObject(target[k])) {
      target[k] = mergePreferDefined({ ...target[k] }, v);
    } else {
      target[k] = v;
    }
  }
  return target;
}

function safeFirstJson(nodeName) {
  try {
    const arr = $items(nodeName);
    if (!Array.isArray(arr) || arr.length === 0) return {};
    if (arr.length === 1) return arr[0].json ?? {};
    return (arr[$itemIndex]?.json ?? arr[0]?.json ?? {});
  } catch {
    return {};
  }
}

function findAiRaw(obj) {
  const cands = [
    obj?.output,
    obj?.ai?.output,
    obj?.ai_output,
    obj?.aiOutput,
    obj?.llm?.output,
    obj?.agent?.output,
    obj?.normalize_confidence?.output,
    obj?.ai_result?.output,
  ];
  for (const v of cands) {
    if (typeof v === "string" && v.trim()) return v;
  }
  // Sometimes output is an array like: [{ output: "{...json...}" }]
  if (
    Array.isArray(obj?.output) &&
    obj.output.length === 1 &&
    typeof obj.output[0]?.output === "string"
  ) {
    return obj.output[0].output;
  }
  // Last resort: scan top-level string fields for JSON-ish content
  if (obj && typeof obj === "object") {
    for (const v of Object.values(obj)) {
      if (typeof v === "string" && v.includes("{") && v.includes("}")) return v;
    }
  }
  return null;
}

function normOptDecision(v) {
  if (!v) return "WAIT";
  const s = String(v).trim().toUpperCase();
  if (s === "BUY_CALL" || s === "BUY_PUT" || s === "WAIT") return s;
  return "WAIT";
}

function fmtStr(x, dp = 2) {
  const n = safeNum(x);
  if (n == null) return "n/a";
  return Number(n.toFixed(dp));
}

function fmtPctSmart(x) {
  const n = safeNum(x);
  if (n == null) return "n/a";
  return `${(n * 100).toFixed(2)}%`;
}

function fmtDelta(x) {
  const n = safeNum(x);
  if (n == null) return "n/a";
  return (n >= 0 ? "+" : "") + n.toFixed(3);
}

function inferSideFromOptDecision(dec) {
  if (dec === "BUY_PUT") return "PUT";
  if (dec === "BUY_CALL") return "CALL";
  return null;
}

// --------------------------------------------------
// 1) Parse AI output (but DO NOT merge it wholesale)
// --------------------------------------------------
const aiRaw = findAiRaw($json);
const aiParsed = parseMaybeJson(aiRaw);

let aiPlan = {};
if (isPlainObject(aiParsed)) aiPlan = aiParsed;
else if (
  Array.isArray(aiParsed) &&
  aiParsed.length === 1 &&
  isPlainObject(aiParsed[0])
) {
  aiPlan = aiParsed[0];
}

// --------------------------------------------------
// 2) Build deterministic payload (source of truth)
// --------------------------------------------------
let trend = {};
try {
  trend = $node["Compute Trend & Confidence"].json ?? {};
} catch {
  trend = {};
}
if (!isPlainObject(trend) || Object.keys(trend).length === 0) {
  trend = safeFirstJson("Compute Trend & Confidence");
}

let basePlan = {};
try {
  basePlan = $node["Compare Candidates"].json ?? {};
} catch {
  basePlan = {};
}
if (!isPlainObject(basePlan) || Object.keys(basePlan).length === 0) {
  basePlan = safeFirstJson("Compare Candidates");
}

let enrich = {};
try {
  enrich = $node["Enrich Payload for AI"].json ?? {};
} catch {
  enrich = {};
}
if (!isPlainObject(enrich) || Object.keys(enrich).length === 0) {
  enrich = safeFirstJson("Enrich Payload for AI");
}

const payload = {};
mergePreferDefined(payload, trend);
mergePreferDefined(payload, basePlan);
mergePreferDefined(payload, enrich);

// Merge current item ONLY for non-AI, non-critical fields (avoid AI overriding truth)
const current = isPlainObject($json) ? $json : {};
const aiTopKeys = new Set(Object.keys(aiPlan || {}));
const deny = new Set([
  ...aiTopKeys,
  "optionContext",
  "key_factors",
  "plain_explanation",
  "explanation",
]);

for (const [k, v] of Object.entries(current)) {
  if (v === undefined || v === null) continue;
  if (deny.has(k)) continue;
  // only fill missing top-level fields (don't override deterministic)
  if (payload[k] === undefined || payload[k] === null) payload[k] = v;
}

// --------------------------------------------------
// 3) Allowlist AI fields: explanation only
// --------------------------------------------------
payload.ai_debug = {
  desired_option_right_ai: aiPlan.desired_option_right ?? null,
  option_contract_symbol_ai: aiPlan.option_contract_symbol ?? null,
  option_decision_ai: aiPlan.option_decision ?? null,
  confidence_ai: aiPlan.confidence ?? null,
};

if (Array.isArray(aiPlan.key_factors)) payload.key_factors = aiPlan.key_factors;

let explanation =
  typeof aiPlan.plain_explanation === "string" && aiPlan.plain_explanation.trim()
    ? aiPlan.plain_explanation.trim()
    : typeof aiPlan.explanation === "string" && aiPlan.explanation.trim()
      ? aiPlan.explanation.trim()
      : typeof payload.plain_explanation === "string"
        ? payload.plain_explanation.trim()
        : "";

// --------------------------------------------------
// 4) Pull summary fields
// --------------------------------------------------
const ticker = payload.ticker || "n/a";
const tf = payload.overall_timeframe || payload.timeframes || "n/a";

const direction =
  payload.trend_direction_pre ||
  payload.trend_direction ||
  payload.direction ||
  aiPlan.trend_direction ||
  "n/a";

const strength =
  payload.trend_strength_pre ||
  payload.trend_strength ||
  aiPlan.trend_strength ||
  "n/a";

const strengthScore =
  safeNum(payload.trend_strength_score_pre) ??
  safeNum(payload.trend_strength_score) ??
  safeNum(aiPlan.trend_strength_score);

const strengthScoreTxt = strengthScore != null ? Math.round(strengthScore) : "n/a";

const alignment =
  payload.alignment_pre || payload.alignment || aiPlan.alignment || "n/a";

const adxConf =
  payload.adx_confirmation_pre ||
  payload.adx_confirmation ||
  aiPlan.adx_confirmation ||
  "n/a";

const bias =
  payload.technical_bias || payload.bias || aiPlan.technical_bias || "n/a";

const conf =
  safeNum(payload.confidence_pre) ??
  safeNum(payload.confidence) ??
  safeNum(aiPlan.confidence);

const confTxt =
  conf != null ? `${Math.round(conf > 1 ? conf : conf * 100)}%` : "n/a";

const trig = safeNum(payload.trigger_price);
const inv = safeNum(payload.invalidation_level);
const tgt = safeNum(payload.target_level);

const missingLevels = trig == null || inv == null || tgt == null;

// --------------------------------------------------
// 5) Decision + WHY WAIT logic
// --------------------------------------------------
const aiOptDecisionRaw = normOptDecision(aiPlan.option_decision);
const aiOptDecision = aiOptDecisionRaw;

// Accept AI decision ONLY if deterministic decision is absent (still subject to gates)
const optDecision = normOptDecision(
  payload.option_decision ||
    payload.option_trade_decision ||
    aiPlan.option_decision ||
    "WAIT"
);

// If workflow did not provide a deterministic option_decision, accept the AI decision (still subject to gates)
if (
  payload.option_decision == null &&
  payload.option_trade_decision == null &&
  aiPlan.option_decision != null
) {
  payload.option_decision = normOptDecision(aiPlan.option_decision);
}

const overrideReasons = [];
if (payload.time_gate_ok === false)
  overrideReasons.push(
    `time_gate_ok=false (${payload.time_gate_reason ?? "n/a"})`
  );
if (payload.option_liquidity_ok === false)
  overrideReasons.push(
    `option_liquidity_ok=false (${payload.option_liquidity_reason ?? "n/a"})`
  );

if (payload.candidate_pass === false) overrideReasons.push("candidate_pass=false");
if (payload.candidate_pass == null)
  overrideReasons.push(
    "candidate_pass is missing (treated as fail by Compare Candidates)"
  );

// RR handling (UPDATED — reference-first)
// RR should NOT be used as an override reason unless it is WAY too low.
const rr = safeNum(payload.option_risk_reward);
const RR_WAY_TOO_LOW = 0.6;
if (rr != null && rr < RR_WAY_TOO_LOW) {
  overrideReasons.push(
    `option_risk_reward ${rr.toFixed(2)} < ${RR_WAY_TOO_LOW} (RR way too low)`
  );
}

if (missingLevels)
  overrideReasons.push("missing underlying levels (trigger/invalidation/target)");

if (aiOptDecision !== "WAIT" && optDecision === "WAIT") {
  const reasonTxt = overrideReasons.length
    ? overrideReasons.join("; ")
    : "deterministic rules forced WAIT";
  const note = `NOTE: AI suggested ${aiOptDecisionRaw}, but overridden to WAIT: ${reasonTxt}.`;
  explanation = explanation ? `${note}\n${explanation}` : note;
  payload.plain_explanation = explanation;
}

if (!explanation) explanation = "n/a";

// Winner / Other
const winnerSide =
  String(payload.winner_side || "").toUpperCase().trim() ||
  String(payload.candidate_side || "").toUpperCase().trim() ||
  inferSideFromOptDecision(optDecision) ||
  "n/a";

const other = isPlainObject(payload.other_candidate) ? payload.other_candidate : null;

// Option quote
const right =
  payload.desired_option_right ||
  payload.winner_right ||
  payload.option_right ||
  payload.right ||
  aiPlan.desired_option_right ||
  "n/a";

const sym =
  payload.option_contract_symbol ||
  payload.option_symbol ||
  aiPlan.option_contract_symbol ||
  "n/a";

const bid = safeNum(payload.option_bid ?? payload.quote?.bid);
const ask = safeNum(payload.option_ask ?? payload.quote?.ask);
const mid = safeNum(payload.option_mid ?? payload.quote?.mid);
const sp = safeNum(payload.option_spread_pct ?? payload.quote?.spread_pct);

const entry = safeNum(payload.option_entry_premium);
const stop = safeNum(payload.option_stop_premium);
const tp = safeNum(payload.option_take_profit_premium);
const rrTxt =
  safeNum(payload.option_risk_reward) != null
    ? Number(safeNum(payload.option_risk_reward).toFixed(2))
    : "n/a";

// Underlying RR (optional)
const uRR = safeNum(payload.underlying_risk_reward);
const uRRTxt = uRR != null ? Number(uRR.toFixed(2)) : "n/a";

// --------------------------------------------------
// 6) Render Telegram message
// --------------------------------------------------
const lines = [];

lines.push("Options Multi-TF Summary");
lines.push(`Ticker: ${ticker}`);
lines.push(`Timeframes: ${tf}`);
lines.push(`Direction: ${direction}`);
lines.push(`Strength: ${strength} (score ${strengthScoreTxt})`);
lines.push(`Alignment: ${alignment}`);
lines.push(`ADX confirmation: ${adxConf}`);
lines.push(`Bias: ${bias}`);
lines.push(`Confidence: ${confTxt}`);
lines.push(
  `Underlying Levels: Trigger: ${fmtStr(trig, 2)} | Invalidation: ${fmtStr(inv, 2)} | Target: ${fmtStr(tgt, 2)}`
);

// --- NEW: Candlestick summaries (Hammer / Engulfing / ShootingStar) ---
try {
  const tfs =
    payload.timeframes && typeof payload.timeframes === "object"
      ? Object.keys(payload.timeframes)
      : [];
  if (tfs.length) {
    lines.push("");
    lines.push("🕯 Candles (Hammer / BullEngulf / BearEngulf / ShootingStar)");
    for (const tf of tfs) {
      const h = payload.timeframes?.[tf]?.hammer;
      const e = payload.timeframes?.[tf]?.bullish_engulfing;
      const be = payload.timeframes?.[tf]?.bearish_engulfing;
      const s = payload.timeframes?.[tf]?.shooting_star;

      const parts = [];

      if (h && h.present === true) parts.push(`Hammer=${h.type || "hammer"} ✅`);
      else parts.push("Hammer=none");

      if (e && e.present === true)
        parts.push(`BullEngulf=${e.type || "bullish_engulfing"} ✅`);
      else parts.push("BullEngulf=none");

      if (be && be.present === true)
        parts.push(`BearEngulf=${be.type || "bearish_engulfing"} ✅`);
      else parts.push("BearEngulf=none");

      if (s && s.present === true)
        parts.push(`ShootingStar=${s.type || "shooting_star"} ✅`);
      else parts.push("ShootingStar=none");

      lines.push(`${tf}: ${parts.join(" | ")}`);
    }
  }
} catch (e) {}

lines.push("");
lines.push("🧭 Candidate Compare");
lines.push(`Winner: ${winnerSide}`);
if (other) {
  const oSide = String(other.candidate_side || "n/a").toUpperCase();
  const oSym = other.option_contract_symbol || "n/a";
  const oPass =
    other.candidate_pass === true || other.candidate_pass === false
      ? String(other.candidate_pass)
      : "n/a";
  const oSp = fmtPctSmart(other.option_spread_pct);
  const oRR =
    safeNum(other.option_risk_reward) != null
      ? Number(safeNum(other.option_risk_reward).toFixed(2))
      : "n/a";
  const oDelta = fmtDelta(other.option_delta);
  lines.push(
    `Other: ${oSide} | ${oSym} | pass=${oPass} | spread%=${oSp} | RR=${oRR} | Δ ${oDelta}`
  );
} else {
  lines.push("Other: N/A");
}

lines.push("");
lines.push("🧾 Option Trade Plan");
lines.push(
  `Decision: ${
    optDecision === "WAIT"
      ? "🟡 WAIT"
      : optDecision === "BUY_PUT"
        ? "🔴 BUY_PUT"
        : "🟢 BUY_CALL"
  } @ ${sym}`
);
lines.push(
  `Quote: Right: ${right} | Bid: ${fmtStr(bid, 2)} | Ask: ${fmtStr(ask, 2)} | Mid: ${fmtStr(mid, 3)} | Spread%: ${fmtPctSmart(sp)}`
);
lines.push(
  `Entry: ${fmtStr(entry, 2)} | Stop: ${fmtStr(stop, 2)} | TP: ${fmtStr(tp, 2)} | R:R ${rrTxt}`
);

lines.push("");
lines.push("🧾 Trade Plan (Underlying)");
lines.push(`Decision: 🟡 WAIT @ ${fmtStr(trig, 2)}`);
lines.push(
  `Entry: ${fmtStr(trig, 2)} | Stop: ${fmtStr(inv, 2)} | TP: ${fmtStr(tgt, 2)} | R:R ${uRRTxt}`
);

if (Array.isArray(payload.key_factors) && payload.key_factors.length) {
  lines.push("");
  lines.push("Key factors:");
  for (const k of payload.key_factors) lines.push(`• ${String(k)}`);
}

lines.push("");
lines.push(`Explanation: ${explanation}`);

return { json: { ...payload, text: lines.join("\n") } };

// n8n Function node

function getText(item) {
  return (
    item.json?.message?.text ??
    item.json?.body?.message?.text ??
    item.json?.text ??
    item.json?.message ??
    item.json?.body?.text ??
    ""
  );
}

const item = items[0];
const textRaw = String(getText(item)).trim();

// Matches:
// "SPY"
// "SPY S"
// "SPY M"
// "SPY L"
const m = textRaw.match(/^\s*([A-Za-z0-9.\-_]{1,15})(?:\s+([SMLsml]))?\b/);

if (!m) {
  throw new Error(`Cannot parse Telegram message text: "${textRaw}"`);
}

const symbol = m[1].toUpperCase();
const profile = (m[2] ? m[2].toUpperCase() : "S"); // <-- default to S

const profileMap = {
  S: ["2m", "3m", "5m"],
  M: ["1m", "5m", "15m"],
  L: ["5m", "1h", "1d"], // daily = 1d
};

const intervals = profileMap[profile];
if (!intervals) {
  throw new Error(`Unknown profile "${profile}". Use S, M, or L. Input was: "${textRaw}"`);
}

return [
  {
    json: {
      symbol,
      mode:"MANUAL",
      chatId:$input.first().json.message.chat.id,
      profile,                     // S/M/L
      intervals,                   // ["1m","2m","5m"] etc
      intervals_csv: intervals.join(","),
      route: `${symbol}_${profile}`, // e.g. "SPY_S"
      telegram_text: textRaw,
      requested_at: new Date().toISOString(),
    },
  },
];

// n8n Function node
// AFTER Merge node, BEFORE AI node (multi-timeframe DMI + Demark + Price Structure)

function safeNum(x) {
  if (typeof x === 'number' && Number.isFinite(x)) return x;
  if (typeof x === 'string') {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function dmiDirection(diPlus, diMinus) {
  if (diPlus == null || diMinus == null) return 'unknown';
  if (diPlus > diMinus) return 'bullish';
  if (diMinus > diPlus) return 'bearish';
  return 'flat';
}

function adxStrength(adx) {
  if (adx == null) return 'unknown';
  if (adx >= 50) return 'very_strong';
  if (adx >= 25) return 'moderate';
  return 'weak';
}

function adxSlope3(series) {
  if (!Array.isArray(series)) return null;
  const valid = series.map(p => safeNum(p?.adx)).filter(v => v != null);
  if (valid.length < 3) return null;
  return valid[valid.length - 1] - valid[valid.length - 3];
}

function normalizeTf(tf) {
  if (!tf) return 'unknown';
  const s = String(tf).trim();
  if (s === '120s' || s === '2min') return '2m';
  if (s === '60m') return '1h';
  if (s.toLowerCase() === 'daily') return '1d';
  return s;
}

// Convert timeframe label to minutes (for sorting HTF/MTF/LTF)
function tfToMinutes(tf) {
  const t = normalizeTf(tf);
  const m = t.match(/^(\d+)([mhd])$/i);
  if (!m) return null;
  const n = Number(m[1]);
  const u = m[2].toLowerCase();
  if (!Number.isFinite(n)) return null;
  if (u === 'm') return n;
  if (u === 'h') return n * 60;
  if (u === 'd') return n * 60 * 24;
  return null;
}

// ---- NEW: normalize/validate price object coming from your per-TF indicator node ----
function normalizePrice(p) {
  if (!p || typeof p !== 'object') {
    return {
      last_close: null,
      last_high: null,
      last_low: null,
      swing_n: null,
      swing_high_n: null,
      swing_high_time: null,
      swing_low_n: null,
      swing_low_time: null,
      atr_n: null,
      atr_n_sma: null,
      true_range_avg_n: null,
      swing_effective_n: null,
      atr_effective_n: null,
      reason: 'missing_price'
    };
  }

  return {
    last_close: safeNum(p.last_close),
    last_high:  safeNum(p.last_high),
    last_low:   safeNum(p.last_low),

    swing_n: safeNum(p.swing_n),
    swing_high_n: safeNum(p.swing_high_n),
    swing_high_time: p.swing_high_time ?? null,
    swing_low_n: safeNum(p.swing_low_n),
    swing_low_time: p.swing_low_time ?? null,

    atr_n: safeNum(p.atr_n),
    atr_n_sma: safeNum(p.atr_n_sma),
    true_range_avg_n: safeNum(p.true_range_avg_n),

    swing_effective_n: safeNum(p.swing_effective_n),
    atr_effective_n: safeNum(p.atr_effective_n),

    reason: p.reason ?? null
  };
}


// ---- NEW: normalize/validate hammer pattern ----
function normalizeHammer(h) {
  if (!h || typeof h !== 'object') {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'missing_hammer'
    };
  }

  return {
    present: h.present === true,
    type: h.type ?? null,
    candleTime: h.candleTime ?? null,
    bodyPct: safeNum(h.bodyPct),
    lowerWickPct: safeNum(h.lowerWickPct),
    upperWickPct: safeNum(h.upperWickPct),
    reason: h.reason ?? null
  };
}


// ---- NEW: normalize/validate shooting star pattern ----
function normalizeShootingStar(s) {
  if (!s || typeof s !== 'object') {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'missing_shooting_star'
    };
  }

  return {
    present: s.present === true,
    type: s.type ?? null,
    candleTime: s.candleTime ?? null,
    bodyPct: safeNum(s.bodyPct),
    lowerWickPct: safeNum(s.lowerWickPct),
    upperWickPct: safeNum(s.upperWickPct),
    reason: s.reason ?? null
  };
}

// ---- NEW: normalize/validate bullish engulfing pattern ----
function normalizeBullishEngulfing(e) {
  if (!e || typeof e !== 'object') {
    return {
      present: false,
      type: null,
      candleTime: null,
      prevTime: null,
      prevBody: null,
      currBody: null,
      reason: 'missing_bullish_engulfing'
    };
  }

  return {
    present: e.present === true,
    type: e.type ?? null,
    candleTime: e.candleTime ?? null,
    prevTime: e.prevTime ?? null,
    prevBody: safeNum(e.prevBody),
    currBody: safeNum(e.currBody),
    reason: e.reason ?? null
  };
}



// ---- NEW: normalize/validate bearish engulfing pattern ----
function normalizeBearishEngulfing(e) {
  if (!e || typeof e !== 'object') {
    return {
      present: false,
      type: null,
      candleTime: null,
      prevTime: null,
      prevBody: null,
      currBody: null,
      reason: 'missing_bearish_engulfing'
    };
  }

  return {
    present: e.present === true,
    type: e.type ?? null,
    candleTime: e.candleTime ?? null,
    prevTime: e.prevTime ?? null,
    prevBody: safeNum(e.prevBody),
    currBody: safeNum(e.currBody),
    reason: e.reason ?? null
  };
}

// Pull from upstream nodes directly
const gp = $('Set Request').first()?.json ?? {};
const sp = $('Set Params').first()?.json ?? {};

// intervals/profile from Set Request (or your Get Profile equivalent)
const EXPECTED = Array.isArray(gp.intervals) && gp.intervals.length
