  }
}

// --- sanitize JSON that contains arithmetic expressions as values ---
// Example:  "target_level": 687.64 - 0.1975  -> "target_level": 687.4425
function safeEvalArithmetic(expr) {
  if (typeof expr !== "string") return null;
  const s = expr.trim();
  if (!/^[0-9+\-*/().\s]+$/.test(s)) return null;
  try {
    // eslint-disable-next-line no-new-func
    const v = Function(`"use strict"; return (${s});`)();
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  } catch {
    return null;
  }
}

function sanitizeJsonArithmetic(text) {
  if (typeof text !== "string") return text;
  return text.replace(/:\s*([0-9+\-*/().\s]+)(?=\s*(,|\}))/g, (match, expr) => {
    const raw = String(expr).trim();
    if (/^[+\-]?\d+(\.\d+)?$/.test(raw)) return match; // already a number
    const v = safeEvalArithmetic(raw);
    if (v == null) return match;
    return `: ${v}`;
  });
}

function parseMaybeJson(x) {
  if (x == null) return null;

  if (typeof x === "object") return x;

  if (typeof x !== "string") return null;

  let t = stripCodeFences(x);
  t = sanitizeJsonArithmetic(t);

