// Approximate NY offset (-04:00 during DST, else -05:00) for a given YYYY-MM-DD.
// Good enough for anchoring "close" timestamps.
function nyOffsetForDate(dateStr) {
  const [Y, M, D] = dateStr.split("-").map(Number);

  function nthSundayUTC(year, monthIndex0, n) {
    const first = new Date(Date.UTC(year, monthIndex0, 1));
    const firstDow = first.getUTCDay(); // 0=Sun
    const firstSundayDay = 1 + ((7 - firstDow) % 7);
    const day = firstSundayDay + (n - 1) * 7;
    return new Date(Date.UTC(year, monthIndex0, day));
  }

  const dstStart = nthSundayUTC(Y, 2, 2);  // 2nd Sunday in March
  const dstEnd = nthSundayUTC(Y, 10, 1);   // 1st Sunday in November

  const day = new Date(Date.UTC(Y, M - 1, D));
  const inDst = day >= dstStart && day < dstEnd;
  return inDst ? "-04:00" : "-05:00";
}

function lastWeekdayYYYYMMDD() {
  const d = new Date();
  // Walk back until Mon–Fri (UTC day-of-week; fine for a fallback date string)
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) {
    d.setUTCDate(d.getUTCDate() - 1);
  }
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

function minutesBackFor(tf) {
  const t = String(tf).trim();
  if (t === "1Min" || t === "1m") return 250;
  if (t === "2Min" || t === "2m") return 500;
  if (t === "5Min" || t === "5m") return 800;
  if (t === "15Min" || t === "15m") return 2000;

  if (t === "1Hour" || t === "60Min" || t === "1h") return 60 * 24 * 10;
  if (t === "1Day" || t === "1d") return 60 * 24 * 120;

  return 600;
}

