// --- Time helper: Alpaca bars use RFC3339 timestamps (usually string), but be defensive ---
function toISOFromAlpaca(t) {
  if (t == null) return null;

  // Common case: RFC3339 string like "2025-12-19T20:59:00Z"
  if (typeof t === 'string') {
    const ms = Date.parse(t);
    if (!Number.isFinite(ms)) return null;
    return new Date(ms).toISOString();
  }

  // Defensive: if numeric, interpret as seconds/ms/ns based on magnitude
  if (typeof t === 'number' && Number.isFinite(t)) {
    let ms = t;
    if (t < 1e11) ms = t * 1000;          // seconds -> ms
    else if (t > 1e14) ms = Math.floor(t / 1e6); // ns -> ms (very defensive)
    const d = new Date(ms);
    return Number.isFinite(d.getTime()) ? d.toISOString() : null;
  }

  return null;
}

/**
