  let atrSma = null;
  let trAvg = null;

  if (atrWin > 0) {
    const slice = trs.slice(trs.length - atrWin);
    const sum = slice.reduce((a, b) => a + b, 0);
    trAvg = sum / atrWin;
    atrSma = trAvg;
