    if (!tIso) continue;
    if (o == null || h == null || l == null || c == null) continue;

    candles.push({
      t: tIso,
      o,
      h,
      l,
      c,
      v: v == null ? 0 : v,
    });
  }

  // Ensure ascending time
  candles.sort((a, b) => new Date(a.t) - new Date(b.t));

  return {
    candles,
    reason: candles.length ? null : 'All bars were filtered out (missing OHLC or invalid timestamps)',
    symbol: resolvedSymbol,
    next_page_token: r.next_page_token ?? null,
  };
}

/**
 * Simplified TD Sequential (common baseline)
 * - Setup (9): compares close vs close 4 bars earlier
 *   bullish setup increments when close < close[4]  (downward pressure; often called "buy setup")
 *   bearish setup increments when close > close[4]  (upward pressure; often called "sell setup")
 * - Countdown (13): after setup completes, count nonconsecutive bars:
 *   bullish countdown when close <= low[2]
 *   bearish countdown when close >= high[2]
 */
function computeTDSequential(candles) {
  const n = candles.length;
  const td = new Array(n);

  let bullSetup = 0;
  let bearSetup = 0;

  let cdDir = null;      // 'bullish' | 'bearish'
  let cdCount = 0;
  let setupCompletedIndex = -1;

  for (let i = 0; i < n; i++) {
    td[i] = {
      setupDir: null,
      setupCount: 0,
      setupCompleted: false,
      countdownDir: cdDir,
      countdownCount: cdCount,
      countdownCompleted: false
    };

    // --- SETUP ---
    if (i >= 4) {
      const c0 = candles[i].c;
      const c4 = candles[i - 4].c;

      if (c0 < c4) bullSetup += 1;
      else bullSetup = 0;

      if (c0 > c4) bearSetup += 1;
      else bearSetup = 0;

      let setupDir = null;
      let setupCount = 0;

      if (bullSetup > 0 && bearSetup === 0) {
        setupDir = 'bullish';
        setupCount = bullSetup;
      } else if (bearSetup > 0 && bullSetup === 0) {
        setupDir = 'bearish';
        setupCount = bearSetup;
      } else if (bullSetup > 0 && bearSetup > 0) {
        if (bullSetup >= bearSetup) {
          setupDir = 'bullish';
          setupCount = bullSetup;
        } else {
          setupDir = 'bearish';
          setupCount = bearSetup;
        }
      }

      if (setupCount > 9) setupCount = 9;

      td[i].setupDir = setupDir;
      td[i].setupCount = setupCount;
      td[i].setupCompleted = (setupCount === 9);

      if (td[i].setupCompleted && setupDir) {
        cdDir = setupDir;
        cdCount = 0;
        setupCompletedIndex = i;
      }
    }

    // --- COUNTDOWN ---
    if (cdDir && setupCompletedIndex >= 0 && i > setupCompletedIndex && i >= 2) {
      const c0 = candles[i].c;
      const low2 = candles[i - 2].l;
      const high2 = candles[i - 2].h;

      if (cdDir === 'bullish') {
        if (c0 <= low2) cdCount += 1;
      } else if (cdDir === 'bearish') {
        if (c0 >= high2) cdCount += 1;
      }

      if (cdCount > 13) cdCount = 13;

      td[i].countdownDir = cdDir;
      td[i].countdownCount = cdCount;
      td[i].countdownCompleted = (cdCount === 13);
    } else {
      td[i].countdownDir = cdDir;
      td[i].countdownCount = cdCount;
      td[i].countdownCompleted = (cdCount === 13);
    }
  }

  for (let i = 0; i < n; i++) {
    candles[i].td = td[i];
  }

  const last = n ? candles[n - 1].td : null;

  return {
    candles,
    tdSummary: {
      tf: TF,
      setupDir: last ? last.setupDir : null,
      setupCount: last ? last.setupCount : 0,
      setupCompleted: last ? last.setupCompleted : false,
      countdownDir: last ? last.countdownDir : null,
      countdownCount: last ? last.countdownCount : 0,
      countdownCompleted: last ? last.countdownCompleted : false
    }
  };
}

/**
 * Price structure helpers
 */
function computePriceStructure(candles, swingN, atrN) {
  const n = candles.length;
  if (!n) {
    return {
      last_close: null, last_high: null, last_low: null,
      swing_n: swingN,
      swing_high_n: null, swing_high_time: null,
      swing_low_n: null, swing_low_time: null,
      atr_n: atrN,
      atr_n_sma: null,
      true_range_avg_n: null,
      reason: 'No candles'
    };
  }

  const last = candles[n - 1];

  // --- Swing levels (last N bars) ---
  const win = Math.min(swingN, n);
  let swingHigh = -Infinity, swingLow = Infinity;
  let swingHighTime = null, swingLowTime = null;

  for (let i = n - win; i < n; i++) {
    const c = candles[i];
    if (c.h != null && c.h >= swingHigh) { swingHigh = c.h; swingHighTime = c.t; }
    if (c.l != null && c.l <= swingLow)  { swingLow  = c.l; swingLowTime  = c.t; }
  }

  if (!Number.isFinite(swingHigh)) { swingHigh = null; swingHighTime = null; }
  if (!Number.isFinite(swingLow))  { swingLow  = null; swingLowTime  = null; }

  // --- True Range + ATR (SMA) ---
  const trs = [];
  for (let i = 1; i < n; i++) {
    const cur = candles[i];
    const prev = candles[i - 1];
    if (cur.h == null || cur.l == null || prev.c == null) continue;

    const hl = cur.h - cur.l;
    const hc = Math.abs(cur.h - prev.c);
    const lc = Math.abs(cur.l - prev.c);
    const tr = Math.max(hl, hc, lc);

    if (Number.isFinite(tr)) trs.push(tr);
  }

  const atrWin = Math.min(atrN, trs.length);
  let atrSma = null;
  let trAvg = null;

  if (atrWin > 0) {
    const slice = trs.slice(trs.length - atrWin);
    const sum = slice.reduce((a, b) => a + b, 0);
    trAvg = sum / atrWin;
    atrSma = trAvg;
  }

  return {
    last_close: last.c ?? null,
    last_high: last.h ?? null,
    last_low: last.l ?? null,

    swing_n: swingN,
    swing_high_n: swingHigh,
    swing_high_time: swingHighTime,
    swing_low_n: swingLow,
    swing_low_time: swingLowTime,

    atr_n: atrN,
    atr_n_sma: atrSma,
    true_range_avg_n: trAvg,

    swing_effective_n: win,
    atr_effective_n: atrWin,
    reason: null
  };
}

