// ===== CONFIG =====
const DMI_PERIOD = 14;

// Minimal price structure additions (for trigger/invalidation/target)
const SWING_N = 20;   // swing_high_N / swing_low_N lookback
const ATR_N   = 14;   // ATR lookback (SMA of True Range)
// ==================

function computeDMI(candles, period) {
  if (!candles || candles.length <= period + 2) {
    return {
      status: 'insufficient_data',
      reason: 'Not enough candles for DMI',
      series: [],
      summary: { latest: null, crossover: null, trendStrength: 'weak' }
    };
  }

  // candles assumed sorted ascending
  const plusDM = [];
  const minusDM = [];
  const tr = [];

  for (let i = 1; i < candles.length; i++) {
    const curr = candles[i];
    const prev = candles[i - 1];

    const upMove = curr.h - prev.h;
    const downMove = prev.l - curr.l;

    let plus = 0, minus = 0;
    if (upMove > downMove && upMove > 0) plus = upMove;
    if (downMove > upMove && downMove > 0) minus = downMove;

    plusDM.push(plus);
    minusDM.push(minus);

    const tr1 = curr.h - curr.l;
    const tr2 = Math.abs(curr.h - prev.c);
    const tr3 = Math.abs(curr.l - prev.c);
    tr.push(Math.max(tr1, tr2, tr3));
  }

  const smooth = (values) => {
    const out = new Array(values.length).fill(null);
    let sum = 0;
    for (let i = 0; i < period; i++) sum += values[i];
    out[period - 1] = sum;
    for (let i = period; i < values.length; i++) {
      const prev = out[i - 1];
      out[i] = prev - prev / period + values[i];
    }
    return out;
  };

  const plusDMs = smooth(plusDM);
  const minusDMs = smooth(minusDM);
  const trs = smooth(tr);

  const diPlusArr = [];
  const diMinusArr = [];
  const dxArr = [];

  for (let i = 0; i < plusDM.length; i++) {
    if (i < period - 1 || trs[i] === null) {
      diPlusArr.push(null);
      diMinusArr.push(null);
      dxArr.push(null);
      continue;
    }

    const p = plusDMs[i];
    const m = minusDMs[i];
    const t = trs[i];

    const diPlus = t === 0 ? 0 : (p / t) * 100;
    const diMinus = t === 0 ? 0 : (m / t) * 100;

    diPlusArr.push(diPlus);
    diMinusArr.push(diMinus);

    const denom = diPlus + diMinus;
    const dx = denom === 0 ? 0 : (Math.abs(diPlus - diMinus) / denom) * 100;
    dxArr.push(dx);
  }

  // ADX
  const adxArr = new Array(dxArr.length).fill(null);
  let adx = null;

  const firstDX = dxArr.findIndex(v => v !== null);
  if (firstDX !== -1 && firstDX + period <= dxArr.length) {
    let sumDX = 0;
    for (let i = firstDX; i < firstDX + period; i++) sumDX += dxArr[i];
    adx = sumDX / period;
    adxArr[firstDX + period - 1] = adx;

    for (let i = firstDX + period; i < dxArr.length; i++) {
      adx = ((adx * (period - 1)) + dxArr[i]) / period;
      adxArr[i] = adx;
    }
  }

  const series = [];
  for (let i = 0; i < dxArr.length; i++) {
    series.push({
      t: candles[i + 1].t,
      diPlus: diPlusArr[i],
      diMinus: diMinusArr[i],
      adx: adxArr[i]
    });
  }

  const valid = series.filter(p => p.diPlus !== null && p.adx !== null);
  if (valid.length < 2) {
    return {
      status: 'partial',
      reason: 'DMI computed but ADX not stable yet',
      series,
      summary: { latest: valid.length ? valid[valid.length - 1] : null, crossover: null, trendStrength: 'weak' }
    };
  }

  const latest = valid[valid.length - 1];
  const prev = valid[valid.length - 2];

  let crossover = null;
  const prevRel = prev.diPlus - prev.diMinus;
  const currRel = latest.diPlus - latest.diMinus;
  if (prevRel <= 0 && currRel > 0) crossover = 'bullish_cross_up';
  else if (prevRel >= 0 && currRel < 0) crossover = 'bearish_cross_down';

  let trendStrength = 'weak';
  if (latest.adx >= 50) trendStrength = 'very_strong';
  else if (latest.adx >= 25) trendStrength = 'moderate';

  return {
    status: 'ok',
    reason: null,
    series,
    summary: { latest, crossover, trendStrength }
  };
}

/**
 * NEW: price structure output so AI can compute trigger/invalidation/target
 * Requires only candles (o/h/l/c).
 *
 * Returns:
 * - last_close, last_high, last_low
 * - swing_high_n, swing_low_n (+ timestamps)
 * - atr_n_sma (SMA of True Range), true_range_avg_n
 */
function computePriceStructure(candles, swingN, atrN) {
  const n = Array.isArray(candles) ? candles.length : 0;
  if (!n) {
    return {
      last_close: null, last_high: null, last_low: null,
      swing_n: swingN,
      swing_high_n: null, swing_high_time: null,
      swing_low_n: null, swing_low_time: null,
      atr_n: atrN,
      atr_n_sma: null,
      true_range_avg_n: null,
      swing_effective_n: 0,
      atr_effective_n: 0,
      reason: 'No candles'
    };
  }

  const last = candles[n - 1];

  // --- Swing levels over last N bars ---
  const win = Math.min(swingN, n);
  let swingHigh = -Infinity, swingLow = Infinity;
  let swingHighTime = null, swingLowTime = null;

  for (let i = n - win; i < n; i++) {
    const c = candles[i];
    if (c?.h != null && c.h >= swingHigh) { swingHigh = c.h; swingHighTime = c.t; }
    if (c?.l != null && c.l <= swingLow)  { swingLow  = c.l; swingLowTime  = c.t; }
  }

  if (!Number.isFinite(swingHigh)) { swingHigh = null; swingHighTime = null; }
  if (!Number.isFinite(swingLow))  { swingLow  = null; swingLowTime  = null; }

  // --- True Range series ---
  const trs = [];
  for (let i = 1; i < n; i++) {
    const cur = candles[i];
    const prev = candles[i - 1];
    if (cur?.h == null || cur?.l == null || prev?.c == null) continue;

    const hl = cur.h - cur.l;
    const hc = Math.abs(cur.h - prev.c);
    const lc = Math.abs(cur.l - prev.c);
    const tr = Math.max(hl, hc, lc);

    if (Number.isFinite(tr)) trs.push(tr);
  }

  // --- ATR as SMA(TR, atrN) ---
  const atrWin = Math.min(atrN, trs.length);
  let atrSma = null;
  let trAvg = null;

  if (atrWin > 0) {
    const slice = trs.slice(trs.length - atrWin);
    const sum = slice.reduce((a, b) => a + b, 0);
    trAvg = sum / atrWin;
    atrSma = trAvg;
  }

  return {
    last_close: last?.c ?? null,
    last_high: last?.h ?? null,
    last_low: last?.l ?? null,

    swing_n: swingN,
    swing_high_n: swingHigh,
    swing_high_time: swingHighTime,
    swing_low_n: swingLow,
    swing_low_time: swingLowTime,

    atr_n: atrN,
    atr_n_sma: atrSma,
    true_range_avg_n: trAvg,

    swing_effective_n: win,
    atr_effective_n: atrWin,
    reason: null
  };
}



// ---- NEW: Hammer candlestick detection (last candle) ----
// Notes:
// - A "hammer" typically has a small real body near the top of the range and a long lower wick.
// - This function only detects the candle geometry (no trend context).
// - If close < open, the same geometry is often called a "hanging man".
function computeHammer(candles) {
  if (!Array.isArray(candles) || candles.length === 0) {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'No candles'
    };
  }

  const last = candles[candles.length - 1] || {};
  const o = Number(last.o);
  const h = Number(last.h);
  const l = Number(last.l);
  const c = Number(last.c);

  if (![o,h,l,c].every(Number.isFinite)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'Non-finite OHLC'
    };
  }

  const range = h - l;
  if (!(range > 0)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'Invalid range'
    };
  }

  const body = Math.abs(c - o);
  const upper = h - Math.max(o, c);
  const lower = Math.min(o, c) - l;

  const bodyPct = body / range;
  const upperPct = upper / range;
  const lowerPct = lower / range;

  // Tunables: keep conservative defaults
  const smallBody = bodyPct <= 0.35;
  const longLower = lower >= 2 * body;
  const smallUpper = upper <= 0.75 * body; // allow tiny upper wick

  const present = !!(smallBody && longLower && smallUpper);
  const type = present
    ? (c >= o ? 'hammer' : 'hanging_man')
    : null;

  return {
    present,
    type,
    candleTime: last.t ?? null,
    bodyPct: Number.isFinite(bodyPct) ? bodyPct : null,
    lowerWickPct: Number.isFinite(lowerPct) ? lowerPct : null,
    upperWickPct: Number.isFinite(upperPct) ? upperPct : null,
    reason: present ? null : 'Candle geometry did not meet hammer thresholds'
  };
}
// ---- NEW: Shooting Star / Inverted Hammer detection (last candle) ----
// Notes:
// - Geometry-only detection (no trend context).
// - Shooting star / inverted hammer: small real body with long upper wick and small lower wick.
// - Type mapping by candle color:
//   * close >= open => 'inverted_hammer' (often bullish context)
//   * close < open  => 'shooting_star'   (often bearish context)
function computeShootingStar(candles) {
  if (!Array.isArray(candles) || candles.length === 0) {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
