  let swingHigh = -Infinity, swingLow = Infinity;
  let swingHighTime = null, swingLowTime = null;

  for (let i = n - win; i < n; i++) {
    const c = candles[i];
    if (c?.h != null && c.h >= swingHigh) { swingHigh = c.h; swingHighTime = c.t; }
    if (c?.l != null && c.l <= swingLow)  { swingLow  = c.l; swingLowTime  = c.t; }
  }

  if (!Number.isFinite(swingHigh)) { swingHigh = null; swingHighTime = null; }
  if (!Number.isFinite(swingLow))  { swingLow  = null; swingLowTime  = null; }

  // --- True Range series ---
  const trs = [];
  for (let i = 1; i < n; i++) {
    const cur = candles[i];
    const prev = candles[i - 1];
    if (cur?.h == null || cur?.l == null || prev?.c == null) continue;

    const hl = cur.h - cur.l;
    const hc = Math.abs(cur.h - prev.c);
    const lc = Math.abs(cur.l - prev.c);
    const tr = Math.max(hl, hc, lc);

    if (Number.isFinite(tr)) trs.push(tr);
  }

  // --- ATR as SMA(TR, atrN) ---
  const atrWin = Math.min(atrN, trs.length);
  let atrSma = null;
  let trAvg = null;

  if (atrWin > 0) {
    const slice = trs.slice(trs.length - atrWin);
    const sum = slice.reduce((a, b) => a + b, 0);
    trAvg = sum / atrWin;
    atrSma = trAvg;
  }

  return {
    last_close: last?.c ?? null,
    last_high: last?.h ?? null,
    last_low: last?.l ?? null,

    swing_n: swingN,
    swing_high_n: swingHigh,
    swing_high_time: swingHighTime,
    swing_low_n: swingLow,
    swing_low_time: swingLowTime,

    atr_n: atrN,
    atr_n_sma: atrSma,
    true_range_avg_n: trAvg,

    swing_effective_n: win,
    atr_effective_n: atrWin,
    reason: null
  };
}



// ---- NEW: Hammer candlestick detection (last candle) ----
// Notes:
// - A "hammer" typically has a small real body near the top of the range and a long lower wick.
// - This function only detects the candle geometry (no trend context).
// - If close < open, the same geometry is often called a "hanging man".
function computeHammer(candles) {
  if (!Array.isArray(candles) || candles.length === 0) {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'No candles'
    };
  }

  const last = candles[candles.length - 1] || {};
  const o = Number(last.o);
  const h = Number(last.h);
  const l = Number(last.l);
  const c = Number(last.c);

  if (![o,h,l,c].every(Number.isFinite)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'Non-finite OHLC'
    };
  }

  const range = h - l;
  if (!(range > 0)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'Invalid range'
    };
  }

  const body = Math.abs(c - o);
  const upper = h - Math.max(o, c);
  const lower = Math.min(o, c) - l;

  const bodyPct = body / range;
  const upperPct = upper / range;
  const lowerPct = lower / range;

  // Tunables: keep conservative defaults
  const smallBody = bodyPct <= 0.35;
  const longLower = lower >= 2 * body;
  const smallUpper = upper <= 0.75 * body; // allow tiny upper wick

  const present = !!(smallBody && longLower && smallUpper);
  const type = present
    ? (c >= o ? 'hammer' : 'hanging_man')
    : null;

  return {
    present,
    type,
    candleTime: last.t ?? null,
    bodyPct: Number.isFinite(bodyPct) ? bodyPct : null,
    lowerWickPct: Number.isFinite(lowerPct) ? lowerPct : null,
    upperWickPct: Number.isFinite(upperPct) ? upperPct : null,
    reason: present ? null : 'Candle geometry did not meet hammer thresholds'
  };
}
// ---- NEW: Shooting Star / Inverted Hammer detection (last candle) ----
// Notes:
// - Geometry-only detection (no trend context).
// - Shooting star / inverted hammer: small real body with long upper wick and small lower wick.
// - Type mapping by candle color:
//   * close >= open => 'inverted_hammer' (often bullish context)
//   * close < open  => 'shooting_star'   (often bearish context)
function computeShootingStar(candles) {
  if (!Array.isArray(candles) || candles.length === 0) {
    return {
      present: false,
      type: null,
      candleTime: null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'No candles'
    };
  }

  const last = candles[candles.length - 1] || {};
  const o = Number(last.o);
  const h = Number(last.h);
  const l = Number(last.l);
  const c = Number(last.c);

  if (![o,h,l,c].every(Number.isFinite)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
