  }

  const range = h - l;
  if (!(range > 0)) {
    return {
      present: false,
      type: null,
      candleTime: last.t ?? null,
      bodyPct: null,
      lowerWickPct: null,
      upperWickPct: null,
      reason: 'Zero/negative range'
    };
  }

  const body = Math.abs(c - o);
  const upper = h - Math.max(o, c);
  const lower = Math.min(o, c) - l;

  const bodyPct = body / range;
  const upperPct = upper / range;
  const lowerPct = lower / range;

  const smallBody = bodyPct <= 0.35;
  const longUpper = upper >= 2 * body;
  const smallLower = lower <= 0.75 * body; // allow tiny lower wick

  const present = !!(smallBody && longUpper && smallLower);
  const type = present
    ? (c >= o ? 'inverted_hammer' : 'shooting_star')
    : null;

  return {
    present,
    type,
    candleTime: last.t ?? null,
    bodyPct: Number.isFinite(bodyPct) ? bodyPct : null,
    lowerWickPct: Number.isFinite(lowerPct) ? lowerPct : null,
    upperWickPct: Number.isFinite(upperPct) ? upperPct : null,
    reason: present ? null : 'Candle geometry did not meet shooting star thresholds'
  };
}





// ---- NEW: Bullish Engulfing detection (last 2 candles) ----
// Notes:
// - Bullish engulfing: prior candle bearish (close<open), current candle bullish (close>open),
//   and current real body engulfs prior real body (curr.open <= prev.close && curr.close >= prev.open).
// - Geometry-only detection (no trend context).
function computeBullishEngulfing(candles) {
  if (!Array.isArray(candles) || candles.length < 2) {
    return { present: false, type: null, candleTime: null, prevTime: null, reason: 'Need at least 2 candles' };
  }

  const prev = candles[candles.length - 2] || {};
  const curr = candles[candles.length - 1] || {};

  const po = Number(prev.o); const pc = Number(prev.c);
  const co = Number(curr.o); const cc = Number(curr.c);

  if (![po, pc, co, cc].every(Number.isFinite)) {
    return { present: false, type: null, candleTime: curr.t ?? null, prevTime: prev.t ?? null, reason: 'Non-finite OHLC' };
  }

  const prevBear = pc < po;
  const currBull = cc > co;

  const prevBody = Math.abs(pc - po);
  const currBody = Math.abs(cc - co);

  const engulfsBody = (co <= pc) && (cc >= po);
  const biggerBody = currBody >= prevBody; // mild filter

  const present = !!(prevBear && currBull && engulfsBody && biggerBody);

  return {
    present,
    type: present ? 'bullish_engulfing' : null,
    candleTime: curr.t ?? null,
    prevTime: prev.t ?? null,
    prevBody: Number.isFinite(prevBody) ? prevBody : null,
    currBody: Number.isFinite(currBody) ? currBody : null,
    reason: present ? null : 'Candle geometry did not meet bullish engulfing thresholds'
  };
}


// ---- NEW: Bearish Engulfing detection (last 2 candles) ----
// Notes:
// - Bearish engulfing: prior candle bullish (close>open), current candle bearish (close<open),
//   and current real body engulfs prior real body (curr.open >= prev.close && curr.close <= prev.open).
// - Geometry-only detection (no trend context).
function computeBearishEngulfing(candles) {
  if (!Array.isArray(candles) || candles.length < 2) {
    return { present: false, type: null, candleTime: null, prevTime: null, reason: 'Need at least 2 candles' };
  }

  const prev = candles[candles.length - 2] || {};
  const curr = candles[candles.length - 1] || {};

  const po = Number(prev.o); const pc = Number(prev.c);
  const co = Number(curr.o); const cc = Number(curr.c);

  if (![po, pc, co, cc].every(Number.isFinite)) {
    return { present: false, type: null, candleTime: curr.t ?? null, prevTime: prev.t ?? null, reason: 'Non-finite OHLC' };
  }

  const prevBull = pc > po;
  const currBear = cc < co;

  const prevBody = Math.abs(pc - po);
  const currBody = Math.abs(cc - co);

  const engulfsBody = (co >= pc) && (cc <= po);
  const biggerBody = currBody >= prevBody; // mild filter

  const present = !!(prevBull && currBear && engulfsBody && biggerBody);

  return {
    present,
    type: present ? 'bearish_engulfing' : null,
    candleTime: curr.t ?? null,
    prevTime: prev.t ?? null,
    prevBody: Number.isFinite(prevBody) ? prevBody : null,
    currBody: Number.isFinite(currBody) ? currBody : null,
    reason: present ? null : 'Candle geometry did not meet bearish engulfing thresholds'
  };
}


