// n8n Code node: Parse Order Payload
// MODE: Run Once for Each Item
//
// PURPOSE:
// - Build Alpaca order payload for BOTH:
//   A) Options day-trade (BUY_CALL / BUY_PUT): uses option OCC symbol + premium bracket
//   B) Underlying share trade: uses ticker + share-based bracket
//
// OUTPUT:
// { json: { ...plan, order_payload, order_meta } }
//
// IMPORTANT:
// - This node only PREPARES payload. Your HTTP Request node must post it to Alpaca.
// - It does NOT place any order by itself.

function safeNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string") {
    const n = Number.parseFloat(x.trim());
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function upperSymbol(x) {
  if (typeof x !== "string") return null;
  const s = x.trim().toUpperCase();
  return s.length ? s : null;
}

function clampQty(q) {
  const n = safeNum(q);
  if (n == null) return 0;
  return Math.max(0, Math.floor(n));
}

function roundToTick(price, tick) {
  const p = safeNum(price);
  const t = safeNum(tick);
  if (p == null) return null;
  if (t == null || t <= 0) return p;
  return Math.round(p / t) * t;
}

function isValidBracket(entry, stop, tp) {
  const e = safeNum(entry), s = safeNum(stop), t = safeNum(tp);
  if (e == null || s == null || t == null) return false;
  if (e <= 0 || s <= 0 || t <= 0) return false;
  // For long positions: stop < entry < tp
  if (!(s < e && e < t)) return false;
  return true;
}

function pickFirstNonNull(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null) return v;
  }
  return null;
}

// -------------------- main --------------------
const plan = ($json && typeof $json === "object") ? $json : {};

const decisionRaw = String(plan.option_decision || plan.decision || "").toUpperCase();
const isOptionBuy = decisionRaw.startsWith("BUY_CALL") || decisionRaw.startsWith("BUY_PUT");

// Side / Right (for metadata only)
const desiredRight = (plan.desired_option_right || plan.option_right || plan.option_intent?.right || null);

// Qty (should already be computed by your Compute Size node)
const qty = clampQty(plan.qty);

// Basic guardrails
if (decisionRaw === "WAIT" || qty === 0) {
  return {
    json: {
      ...plan,
      order_payload: null,
      order_meta: {
        ok: false,
        reason: decisionRaw === "WAIT" ? "Decision=WAIT" : "qty=0",
        isOptionBuy,
