}

// Tick sizes
// Options premium usually $0.01; if you want nickel increments for cheap options, override via env.
const OPT_TICK = safeNum($env.OPTION_TICK) ?? 0.01;
const EQ_TICK  = safeNum($env.EQUITY_TICK)  ?? 0.01;

// Time in force
const tif = (plan.time_in_force || $env.TIME_IN_FORCE || "day").toString().toLowerCase();

// Order type for entry (limit recommended)
const entryType = (plan.entry_type || $env.ENTRY_TYPE || "limit").toString().toLowerCase();

// -------- Symbol, Entry, Stop, TP selection --------
let symbol, entry, stopLoss, takeProfit;

if (isOptionBuy) {
  symbol = upperSymbol(
    plan.option_contract_symbol ??
    plan.optionContext?.contract?.symbol ??
    plan.selected_option?.contract_symbol ??
    plan.selected_option?.symbol ??
    plan.selected_contract?.symbol
  );

  entry = pickFirstNonNull(
    safeNum(plan.option_entry_premium),
    safeNum(plan.optionContext?.quote?.ask),
    safeNum(plan.option_ask),
    safeNum(plan.optionContext?.quote?.mid),
    safeNum(plan.option_mid)
  );

  stopLoss = pickFirstNonNull(
    safeNum(plan.option_stop_premium)
  );

  takeProfit = pickFirstNonNull(
    safeNum(plan.option_take_profit_premium)
  );

  // Round to option tick
  entry = roundToTick(entry, OPT_TICK);
  stopLoss = roundToTick(stopLoss, OPT_TICK);
  takeProfit = roundToTick(takeProfit, OPT_TICK);

} else {
  symbol = upperSymbol(
    plan.ticker ??
    plan.symbol ??
    plan.underlying ??
    plan.summary?.ticker
  );

  entry = pickFirstNonNull(
    safeNum(plan.entry),
    safeNum(plan.trigger_price),
    safeNum(plan.buy_price),
    safeNum(plan.sell_price)
  );

  stopLoss = pickFirstNonNull(
    safeNum(plan.stop_loss),
    safeNum(plan.invalidation_level)
  );

  takeProfit = pickFirstNonNull(
    safeNum(plan.take_profit),
    safeNum(plan.target_level)
  );

  // Round to equity tick
  entry = roundToTick(entry, EQ_TICK);
  stopLoss = roundToTick(stopLoss, EQ_TICK);
  takeProfit = roundToTick(takeProfit, EQ_TICK);
}

// Validate symbol & bracket
if (!symbol) {
  return {
    json: {
      ...plan,
      order_payload: null,
      order_meta: {
        ok: false,
        reason: "Missing symbol",
        isOptionBuy,
      }
    }
  };
}

const bracketOk = isValidBracket(entry, stopLoss, takeProfit);
if (!bracketOk) {
  return {
    json: {
      ...plan,
      order_payload: null,
      order_meta: {
        ok: false,
        reason: "Invalid bracket prices (need stop < entry < tp, all > 0)",
        isOptionBuy,
        symbol,
        entry,
        stopLoss,
        takeProfit,
      }
    }
  };
}

