// n8n Code node: Compute Size
// MODE: Run Once for Each Item
//
// Options sizing:
// risk_per_contract = (entry_premium - stop_premium) * 100
// qty = floor(maxRiskUsd / risk_per_contract)
//
// Env vars are OPTIONAL (safe-read). If env access is denied, it falls back to input JSON.

function safeNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string") {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function normalizePct(x) {
  const n = safeNum(x);
  if (n == null) return null;
  // allow "0.5" meaning 0.5% OR "0.005" meaning 0.5% (already decimal)
  if (n > 1) return n / 100;
  return n;
}

// SAFE env read: returns null if env access is denied
function envNumSafe(name) {
  try {
    // $env may be blocked by n8n settings; this can throw
    const v = $env?.[name];
    return v == null ? null : safeNum(v);
  } catch (e) {
    return null;
  }
}

function pickFirstNum(...vals) {
  for (const v of vals) {
    const n = safeNum(v);
    if (n != null) return n;
  }
  return null;
}

const plan = ($json && typeof $json === "object") ? $json : {};
const decision = String(plan.option_decision || plan.decision || "").toUpperCase();

// Account (guarded)
const accountJson = $node?.["HTTP Account"]?.json ?? {};
const equity = safeNum(accountJson.equity);
const buyingPower = safeNum(accountJson.buying_power);

// ---- Risk budget (priority order) ----
// 1) Input JSON overrides (recommended)
// 2) Env vars (if allowed)
// 3) Defaults
const inputMaxRiskUsd = pickFirstNum(
  plan.maxRiskUsd,
  plan.max_risk_usd,
  plan.risk?.maxRiskUsd,
  plan.risk_config?.maxRiskUsd
);

const inputMaxRiskPct = normalizePct(
  pickFirstNum(
    plan.maxRiskPct,
    plan.max_risk_pct,
    plan.risk?.maxRiskPct,
    plan.risk_config?.maxRiskPct
  )
);

const envMaxRiskUsd = envNumSafe("MAX_RISK_USD");
const envMaxRiskPct = normalizePct(envNumSafe("MAX_RISK_PCT"));

let maxRiskUsd = null;

if (inputMaxRiskUsd != null) maxRiskUsd = inputMaxRiskUsd;
else if (envMaxRiskUsd != null) maxRiskUsd = envMaxRiskUsd;
else if (inputMaxRiskPct != null && equity != null) maxRiskUsd = equity * inputMaxRiskPct;
else if (envMaxRiskPct != null && equity != null) maxRiskUsd = equity * envMaxRiskPct;
else if (equity != null) maxRiskUsd = equity * 0.005; // default 0.5%
else maxRiskUsd = 25;

// ---- OPTION sizing ----
const isOptionBuy = decision.startsWith("BUY_CALL") || decision.startsWith("BUY_PUT");

if (isOptionBuy) {
  const entry = pickFirstNum(
    plan.option_entry_premium,
    plan.optionContext?.quote?.ask,
    plan.optionContext?.quote?.mid
  );

  const stop = pickFirstNum(
    plan.option_stop_premium,
    plan.option_stop,
    plan.stopPrem,
    plan.stop_premium
  );

  let qty = 0;
  let riskPerContract = null;

  if (entry != null && stop != null) {
    const riskPerShare = entry - stop;
    riskPerContract = riskPerShare > 0 ? riskPerShare * 100 : null;
    if (riskPerContract != null && riskPerContract > 0) {
      qty = Math.floor(maxRiskUsd / riskPerContract);
    }
  }

  qty = Math.max(0, qty);

  return [{
    json: {
      ...plan,
      qty,
      sizing: {
        equity,
        buyingPower,
        maxRiskUsd,
        entry,
        stop,
        riskPerContract,
        qty,
        mode: "options_premium",
        env_access: envMaxRiskUsd != null || envMaxRiskPct != null ? "used" : "not_used_or_denied",
      }
    }
  }];
}

// ---- FALLBACK: underlying sizing ----
const entry =
  pickFirstNum(plan.entry, plan.trigger_price, plan.buy_price, plan.sell_price);

const stop =
  pickFirstNum(plan.stop_loss, plan.invalidation_level);

const riskPerShare = (entry != null && stop != null) ? Math.abs(entry - stop) : null;

let qty = 0;
if (riskPerShare != null && riskPerShare > 0) qty = Math.floor(maxRiskUsd / riskPerShare);
qty = Math.max(0, qty);

return [{
  json: {
    ...plan,
    qty,
    sizing: {
      equity,
      buyingPower,
      maxRiskUsd,
      entry,
      stop,
      riskPerShare,
      qty,
      mode: "underlying",
      env_access: envMaxRiskUsd != null || envMaxRiskPct != null ? "used" : "not_used_or_denied",
    }
  }
}];

/**
