// Return YYYY-MM-DD in a specific timezone (use NY as the trading "date")
function ymdInTzFromAnyDateLike(v, timeZone = "America/New_York") {
  if (!v) return null;
  const ms = Date.parse(v);
  if (!Number.isFinite(ms)) return null;
  const d = new Date(ms);
  // en-CA formats as YYYY-MM-DD
  return new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
