  // 0=Sun, 6=Sat based on UTC day-of-week for the YYYY-MM-DD string
  const dow = new Date(d + "T00:00:00Z").getUTCDay();
  if (dow === 6) d = addDaysYMD(d, 2); // Sat -> Mon
  else if (dow === 0) d = addDaysYMD(d, 1); // Sun -> Mon

