  }

  const tf = intervals["5m"] ? "5m" : (intervals["2m"] ? "2m" : (intervals["1m"] ? "1m" : null));
  if (!tf) return { trigger_price: trig ?? null, invalidation_level: inv ?? null, target_level: tgt ?? null };

  const dmi = intervals[tf]?.dmi || {};
  const price = intervals[tf]?.price || {};

  const diPlus = safeNum(dmi.diPlus);
  const diMinus = safeNum(dmi.diMinus);

  const lastClose = safeNum(price.last_close);
  const swingHigh = safeNum(price.swing_high_n) ?? safeNum(price.last_high);
  const swingLow = safeNum(price.swing_low_n) ?? safeNum(price.last_low);
  const atr = safeNum(price.atr_n_sma) ?? safeNum(price.true_range_avg_n);

  if (lastClose == null) return { trigger_price: trig ?? null, invalidation_level: inv ?? null, target_level: tgt ?? null };

  const dir =
    (diPlus != null && diMinus != null)
      ? (diPlus > diMinus ? "bullish" : (diMinus > diPlus ? "bearish" : null))
      : null;

  const trigger_price = trig ?? lastClose;

  if (inv != null && tgt != null) return { trigger_price, invalidation_level: inv, target_level: tgt };

  if (!dir) return { trigger_price, invalidation_level: inv ?? null, target_level: tgt ?? null };

  if (dir === "bullish") {
    const invalidation_level = inv ?? (swingLow ?? null);
    const target_level = tgt ?? (atr != null ? (lastClose + atr) : null);
    return { trigger_price, invalidation_level, target_level };
  } else {
    const invalidation_level = inv ?? (swingHigh ?? null);
