  if (!oi || typeof oi !== "object") return null;
  return {
    underlying: oi.underlying ?? null,
    right: oi.right ?? null,
    exp_gte: oi.exp_gte ?? null,
    exp_lte: oi.exp_lte ?? null,
    strike_mode: oi.strike_mode ?? null,
    strike_count: safeNum(oi.strike_count) ?? null,
    strike_gte: safeNum(oi.strike_gte) ?? null,
    strike_lte: safeNum(oi.strike_lte) ?? null,
    min_oi: safeNum(oi.min_oi) ?? null,
    max_spread_pct: safeNum(oi.max_spread_pct) ?? null,
    force_right: oi.force_right === true,
    effective_end: oi.effective_end ?? null,
    anchor_ymd: oi.anchor_ymd ?? null,
    fallback_underlying_px: safeNum(fallbackUnderlyingPx) ?? null,
  };
}

function rrLong(entry, stop, tp) {
  const e = safeNum(entry), s = safeNum(stop), t = safeNum(tp);
  if (e == null || s == null || t == null) return null;
  const risk = e - s;
  const reward = t - e;
  if (!(risk > 0) || !(reward > 0)) return null;
  return Number((reward / risk).toFixed(2));
}

function trimOtherCandidate(o) {
  if (!isPlainObject(o)) return null;

  const sym =
    o.option_contract_symbol ??
    o.option_contract ??
    o.option_symbol ??
    o.optionContext?.contract?.symbol ??
    o.contract_symbol ??
    null;

  const greeks = o.optionContext?.greeks ?? o.greeks ?? null;
  const odelta = safeNum(o.option_delta) ?? safeNum(greeks?.delta);

  const q = o.optionContext?.quote ?? o.quote ?? null;
  const obid = safeNum(o.option_bid) ?? safeNum(q?.bid);
  const oask = safeNum(o.option_ask) ?? safeNum(q?.ask);
  const omid = safeNum(o.option_mid) ?? safeNum(q?.mid);
  const osp  = safeNum(o.option_spread_pct) ?? safeNum(q?.spread_pct);

  return {
    candidate_side: o.candidate_side ?? null,
    option_contract_symbol: sym,
    candidate_pass: (o.candidate_pass === true || o.candidate_pass === false) ? o.candidate_pass : null,
    candidate_score: safeNum(o.candidate_score),
    candidate_reasons: o.candidate_reasons ?? o.reasons ?? null,

    option_bid: obid != null ? round2(obid) : null,
    option_ask: oask != null ? round2(oask) : null,
    option_mid: omid != null ? round2(omid) : null,
    option_spread_pct: osp,

    option_risk_reward: safeNum(o.option_risk_reward),
    option_delta: odelta,
  };
}

// ----------------------------------------------------
// 1) Build a proper "base" by merging upstream nodes
// ----------------------------------------------------
const base = {};
mergePreferDefined(base, safeFirstJson("Build AI Payload"));
mergePreferDefined(base, safeFirstJson("Derive Option Intent"));
mergePreferDefined(base, safeFirstJson("Select Contract (Shortlist)"));
mergePreferDefined(base, safeFirstJson("Select Contract (Liquid)"));

// ✅ EXPLICIT: pull Compare Candidates using $node
try {
  mergePreferDefined(base, $node["Compare Candidates"].json);
} catch (e) {
  // ignore if node not found in this execution path
}
// ✅ fallback (some executions prefer $items)
mergePreferDefined(base, safeFirstJson("Compare Candidates"));

// keep Force WAIT last so it can override if it sets anything
mergePreferDefined(base, safeFirstJson("Force WAIT (Liquidity Gate)"));

// ----------------------------------------------------
// 2) Snapshot input (this node’s direct input)
// ----------------------------------------------------
const snapshotsMap = extractSnapshotsMap($json);

// Symbol selection preference: from base, else shortlist, else snapshot-only key
const selected_contract = trimSelectedContract(base.selected_contract || base.selected || null);

let sym =
  base.option_contract_symbol ??
  base.selected_option?.contract_symbol ??
  base.selected_option?.symbol ??
  selected_contract?.symbol ??
  base.optionContext?.contract?.symbol ??
  null;

sym = (typeof sym === "string") ? sym.trim().toUpperCase() : null;

// If symbol doesn't exist in snapshots, but snapshots has exactly one key, use that key
if (snapshotsMap) {
  const keys = Object.keys(snapshotsMap);
  if (sym && !snapshotsMap[sym] && keys.length === 1) sym = keys[0];
  if (!sym && keys.length === 1) sym = keys[0];
}

const occ = sym ? parseOccSymbol(sym) : null;
const snap = (snapshotsMap && sym && snapshotsMap[sym]) ? snapshotsMap[sym] : null;
const snapQuote = computeQuoteFromSnapshot(snap);

// ----------------------------------------------------
// 3) Intervals + deterministic levels (from base)
// ----------------------------------------------------
let intervals = {};
if (isPlainObject(base.intervals) && Object.keys(base.intervals).length > 0 && !isPlainObject(base.timeframes)) {
  intervals = base.intervals;
} else {
  intervals = buildIntervalsFromTimeframes(base.timeframes || {});
}

// ✅ ensure intervals[tf].demark exists (Option A)
intervals = normalizeIntervalsDemark(intervals);

const fallbackUnderlyingPx =
  safeNum(intervals?.["5m"]?.price?.last_close) ??
  safeNum(intervals?.["2m"]?.price?.last_close) ??
  safeNum(intervals?.["1m"]?.price?.last_close) ??
  safeNum(base?.trigger_price) ??
  null;

const computedLevels = computeLevelsIfMissing(
  {
    trigger_price: base.trigger_price,
    invalidation_level: base.invalidation_level,
    target_level: base.target_level,
  },
  intervals
);

const trigger_price = safeNum(base.trigger_price) ?? computedLevels.trigger_price ?? null;
const invalidation_level = safeNum(base.invalidation_level) ?? computedLevels.invalidation_level ?? null;
const target_level = safeNum(base.target_level) ?? computedLevels.target_level ?? null;

// ----------------------------------------------------
// 4) optionContext + liquidity gate (snapshot quote + compare greeks)
// ----------------------------------------------------
const bid = snapQuote.bid ?? safeNum(base.option_bid) ?? safeNum(base.optionContext?.quote?.bid) ?? null;
const ask = snapQuote.ask ?? safeNum(base.option_ask) ?? safeNum(base.optionContext?.quote?.ask) ?? null;
const mid = snapQuote.mid ?? safeNum(base.option_mid) ?? safeNum(base.optionContext?.quote?.mid) ?? ((bid != null && ask != null) ? (bid + ask) / 2 : null);
const spread_pct =
  snapQuote.spread_pct ??
  safeNum(base.option_spread_pct) ??
  safeNum(base.optionContext?.quote?.spread_pct) ??
  ((bid != null && ask != null && mid != null && mid > 0) ? ((ask - bid) / mid) : null);

let selected_option = trimSelectedOption(base.selected_option);
if (!selected_option && occ && sym) {
  selected_option = {
    symbol: sym,
    contract_symbol: sym,
    right: occ.right,
    expiration: occ.expiration,
    strike: occ.strike,
  };
}

// Greeks: prefer snapshot, else Compare Candidates (base.optionContext.greeks)
const greeks =
  snap?.greeks ??
  snap?.latestGreeks ??
  snap?.latest_greeks ??
  base.optionContext?.greeks ??
  base.optionContext?.latestGreeks ??
  base.optionContext?.latest_greeks ??
  base.greeks ??
  null;

// Top-level delta so Telegram can always display it
const option_delta = safeNum(greeks?.delta) ?? safeNum(base.option_delta) ?? null;

// Trade: snapshot first, else upstream
const trade =
  snap?.latestTrade ??
  snap?.latest_trade ??
  base.optionContext?.trade ??
  null;

const optionContext = {
  contract: {
    symbol: sym,
    right: occ?.right ?? base?.option_intent?.right ?? base.option_right ?? null,
    expiration: occ?.expiration ?? selected_option?.expiration ?? selected_contract?.expiration ?? null,
    strike: occ?.strike ?? selected_option?.strike ?? selected_contract?.strike ?? null,
  },
  quote: {
    bid: bid != null ? round2(bid) : null,
    ask: ask != null ? round2(ask) : null,
    mid: mid != null ? round2(mid) : null,
    spread_pct,
  },
  greeks,
  trade,
};

const maxSpreadPct = safeNum(base?.option_intent?.max_spread_pct) ?? 0.02;

let option_liquidity_ok = false;
let option_liquidity_reason = null;

if (bid != null && ask != null && spread_pct != null) {
  if (spread_pct <= maxSpreadPct) {
    option_liquidity_ok = true;
  } else {
    option_liquidity_ok = false;
    option_liquidity_reason = `Spread too wide: ${(spread_pct * 100).toFixed(2)}% > ${(maxSpreadPct * 100).toFixed(2)}%`;
  }
} else {
  option_liquidity_ok = false;
  option_liquidity_reason = "Missing option quote (bid/ask)";
}

// ----------------------------------------------------
// 5) Option premiums: pass-through, else compute fallback
// ----------------------------------------------------
const option_right = base.option_right ?? occ?.right ?? base?.option_intent?.right ?? null;

let option_entry_premium =
  safeNum(base.option_entry_premium) ??
  (ask != null ? ask : (mid != null ? mid : (bid != null ? bid : null)));

let option_stop_premium = safeNum(base.option_stop_premium);
let option_take_profit_premium = safeNum(base.option_take_profit_premium);
let option_risk_reward = safeNum(base.option_risk_reward);

// If stop/tp missing, estimate from underlying move (ONLY if we have levels)
if (option_entry_premium != null && (option_stop_premium == null || option_take_profit_premium == null)) {
  const trig = trigger_price;
  const inv = invalidation_level;
  const tgt = target_level;

  if (trig != null && trig > 0 && inv != null && tgt != null) {
    let riskPct = Math.abs(trig - inv) / trig;
    let rewardPct = Math.abs(tgt - trig) / trig;

    riskPct = clamp(riskPct, 0.05, 0.25) ?? 0.08;
    rewardPct = clamp(rewardPct, 0.07, 0.60) ?? Math.max(0.12, riskPct * 1.6);

    if (option_stop_premium == null) option_stop_premium = Math.max(0.01, option_entry_premium * (1 - riskPct));
    if (option_take_profit_premium == null) option_take_profit_premium = Math.max(0.01, option_entry_premium * (1 + rewardPct));
  }
}

if (option_risk_reward == null) {
  option_risk_reward = rrLong(option_entry_premium, option_stop_premium, option_take_profit_premium);
}

// ----------------------------------------------------
// 6) Final payload
// ----------------------------------------------------
const minimalPayload = {
  // carry forward main plan context
  ticker: base.ticker ?? base.underlying ?? occ?.underlying ?? null,
  overall_timeframe: base.overall_timeframe ?? base.overall_timeframe_hint ?? base?.summary?.overall_timeframe ?? null,

  // indicators / structure
  intervals,

  // deterministic underlying levels
  trigger_price,
  invalidation_level,
  target_level,

  // intent + selections
  option_intent: trimOptionIntent(base.option_intent, fallbackUnderlyingPx),
  selected_contract,
  selected_option,

  option_contract_symbol: sym,
  optionContext,

  // ✅ top-level delta
  option_delta,

  // compare metadata (from Compare Candidates)
  candidate_side: base.candidate_side ?? null,
  derived_right: base.derived_right ?? null,
  time_gate_ok: base.time_gate_ok ?? null,
  time_gate_reason: base.time_gate_reason ?? null,
  other_candidate: trimOtherCandidate(base.other_candidate) ?? null,
  candidate_pass: base.candidate_pass ?? null,
  candidate_score: safeNum(base.candidate_score) ?? null,
  candidate_reasons: base.candidate_reasons ?? null,

  // normalized option fields (AI must not invent)
  option_right,

  option_bid: safeNum(base.option_bid) ?? (bid != null ? round2(bid) : null),
  option_ask: safeNum(base.option_ask) ?? (ask != null ? round2(ask) : null),
  option_mid: safeNum(base.option_mid) ?? (mid != null ? round2(mid) : null),
  option_spread_pct: safeNum(base.option_spread_pct) ?? spread_pct ?? null,

  option_entry_premium: option_entry_premium != null ? round2(option_entry_premium) : null,
  option_stop_premium: option_stop_premium != null ? round2(option_stop_premium) : null,
  option_take_profit_premium: option_take_profit_premium != null ? round2(option_take_profit_premium) : null,
  option_risk_reward: option_risk_reward != null ? Number(option_risk_reward) : null,

  // gates
  option_liquidity_ok,
  option_liquidity_reason,
};

return { json: minimalPayload };

