parameters.jsCode:
// n8n Code node: Verify Option Liquidity (Run Once for Each Item)
// Preserves original JSON output structure and sets:
// - option_liquidity_ok (boolean)
// - option_liquidity_reason (string|null)
// - quote { bid, ask, mid, spread_pct } (or nulls)
// Also mirrors: option_bid/option_ask/option_mid/option_spread_pct
//
// Input expectation:
// $json.snapshots is an OBJECT: { [contractSymbol]: snapshot }
// Alpaca: snapshot.latestQuote.bp (bid), .ap (ask), .t (time)

function isTemplateString(s) {
  return typeof s === "string" && s.includes("{{$") && s.includes("}}");
}

function safeParseMs(s) {
  if (typeof s !== "string" || isTemplateString(s)) return NaN;
  const ms = Date.parse(s);
  return Number.isFinite(ms) ? ms : NaN;
}

function finiteNum(x) {
  return typeof x === "number" && Number.isFinite(x) ? x : null;
}

const snapshots = $json.snapshots;

// Tunables
const maxQuoteAgeSec = finiteNum($json.max_quote_age_sec) ?? 120;
const maxSpreadPct = finiteNum($json.max_spread_pct) ?? 0.02; // 2%

const baseOut = { ...$json }; // preserve everything

// Guard: snapshots must be an object keyed by contract symbol
if (!snapshots || typeof snapshots !== "object" || Array.isArray(snapshots)) {
  return {
    ...baseOut,

    candidate_pass: false,
    candidate_score: 1e6,

    option_liquidity_ok: false,
    option_liquidity_reason:
      "Missing or invalid snapshots (expected object keyed by contract symbol).",
    // preserve downstream shape
    quote: { bid: null, ask: null, mid: null, spread_pct: null },
    option_bid: null,
    option_ask: null,
    option_mid: null,
    option_spread_pct: null,
  };
}

// Iterate and pick “best” passing candidate
let best = null;

// diagnostics
let total = 0;
let missingBidAsk = 0;
let wideSpread = 0;
let staleQuote = 0;

for (const [symbol, snap] of Object.entries(snapshots)) {
  total++;

  const q = snap?.latestQuote;
  const bid = finiteNum(q?.bp);
  const ask = finiteNum(q?.ap);

  if (bid == null || ask == null || ask <= 0 || bid < 0) {
    missingBidAsk++;
    continue;
  }

  const mid = (bid + ask) / 2;
  const spreadPct = mid > 0 ? (ask - bid) / mid : null;

  if (spreadPct == null || spreadPct > maxSpreadPct) {
    wideSpread++;
    continue;
  }

  // quote time
  const quoteMs = safeParseMs(q?.t);
  const nowMs = Date.now();
  const ageSec = Number.isFinite(quoteMs) ? (nowMs - quoteMs) / 1000 : Infinity;

  if (!Number.isFinite(ageSec) || ageSec > maxQuoteAgeSec) {
    staleQuote++;
    continue;
  }

  // choose best: lowest spreadPct, then freshest quote
  if (
    !best ||
    spreadPct < best.spreadPct ||
    (spreadPct === best.spreadPct && ageSec < best.quoteAgeSec)
  ) {
    best = {
      symbol,
      bid,
      ask,
      mid,
      spreadPct,
      quoteTime: q?.t ?? null,
      quoteAgeSec: Number.isFinite(ageSec) ? ageSec : null,
    };
  }
}

if (!best) {
  return {
    ...baseOut,

    candidate_pass: false,
    candidate_score: 1e6,

    option_liquidity_ok: false,
    option_liquidity_reason:
      `No option passed liquidity filters. total=${total}, missingBidAsk=${missingBidAsk}, wideSpread=${wideSpread}, staleQuote=${staleQuote}. ` +
      `Check that you're reading Alpaca quote fields latestQuote.bp/ap.`,
    quote: { bid: null, ask: null, mid: null, spread_pct: null },
    option_bid: null,
    option_ask: null,
    option_mid: null,
    option_spread_pct: null,
  };
}

// Success: write in the SAME STRUCTURE downstream expects
const updatedSelected = (() => {
  const sel = baseOut.selected_option;
  if (sel && typeof sel === "object" && !Array.isArray(sel)) {
    return { ...sel, contract_symbol: best.symbol };
  }
  // if selected_option missing, create minimal structure without breaking
  return { contract_symbol: best.symbol };
})();

return {
  ...baseOut,

  // Candidate gating for Compare Candidates node
  candidate_pass: (typeof baseOut.candidate_pass === "boolean") ? baseOut.candidate_pass : true,
  candidate_score: (typeof baseOut.candidate_score === "number" && Number.isFinite(baseOut.candidate_score))
    ? baseOut.candidate_score
    : Math.round(((best.spreadPct ?? 1) * 100000) + (best.quoteAgeSec ?? 0)),

  // preserve/update contract symbol fields commonly used downstream
  option_contract_symbol: best.symbol,
  selected_option: updatedSelected,

  // REQUIRED by your downstream logic:
  option_liquidity_ok: true,
  option_liquidity_reason: null,

  // Keep the exact quote object shape:
  quote: {
    bid: best.bid,
    ask: best.ask,
    mid: best.mid,
    spread_pct: best.spreadPct,
  },

  // Mirrors (if your other nodes read these):
  option_bid: best.bid,
  option_ask: best.ask,
  option_mid: best.mid,
  option_spread_pct: best.spreadPct,

  // helpful extras (won’t break anything):
  option_quote_time: best.quoteTime,
  option_quote_age_sec: best.quoteAgeSec,
};

// Code node: Force WAIT (Liquidity Gate) - Run Once for Each Item
// Output an AI-like payload forcing WAIT due to liquidity gate.

const base = $json; // comes from Select Contract (Liquid + Gate)

const ticker = base?.ticker || base?.symbol || base?.option_intent?.underlying_symbol || "UNKNOWN";

return {
  ...base,
  option_decision: "WAIT",
  option_contract_symbol: null,
  option_right: base?.option_intent?.right || null,

  option_bid: null,
  option_ask: null,
  option_mid: null,
  option_spread_pct: null,

  option_entry_premium: null,
  option_stop_premium: null,
  option_take_profit_premium: null,
  option_risk_reward: null,

  confidence: base?.confidence ?? 0.0,
  key_factors: [
    ...(Array.isArray(base?.key_factors) ? base.key_factors : []),
    `Liquidity gate: ${base?.option_liquidity_reason || "failed"}`,
    base?.optionContext?.reason ? `Detail: ${base.optionContext.reason}` : null,
  ].filter(Boolean),
  plain_explanation: `Forced WAIT: ${base?.option_liquidity_reason || "Liquidity gate failed"}`
};

// n8n Code node: Select Contract (Shortlist)
// MODE: Run Once for Each Item
//
// OPTION A behavior:
// - Prefer intentRight first (each item already has option_intent.right = call/put)
// - NO default to CALL
// - If no right can be determined, FAIL with candidate_pass=false (instead of silently choosing CALL)
//
// IMPORTANT: Returns ONE OBJECT (not an array) for "Run Once for Each Item"

function safeNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string") {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}
function isPlainObject(x) {
  return x != null && typeof x === "object" && !Array.isArray(x);
}
function unwrapItem(x) {
  if (!isPlainObject(x)) return x;
  if (isPlainObject(x.json)) return x.json;
  return x;
}
function normRight(v) {
  if (!v) return null;
  const s = String(v).trim().toLowerCase();
  if (s === "call" || s === "c") return "call";
  if (s === "put" || s === "p") return "put";
  return null;
}
function getExp(c) {
  const v =
    c?.expiration ||
    c?.expiration_date ||
    c?.exp_date ||
    c?.exp ||
    c?.expiry ||
    null;
  if (!v) return null;
  return String(v).slice(0, 10);
}
function getRight(c) {
  const v = c?.type || c?.right || c?.option_type || null;
  return normRight(v);
}
function getStrike(c) {
  return safeNum(c?.strike_price ?? c?.strike ?? null);
}
function getOi(c) {
  return safeNum(c?.open_interest ?? c?.oi ?? null) ?? 0;
}
function getSpreadPct(c) {
  // If bid/ask exist
  const bid = safeNum(c?.bid ?? c?.quote?.bid ?? null);
  const ask = safeNum(c?.ask ?? c?.quote?.ask ?? null);
  if (bid != null && ask != null && ask > 0) return (ask - bid) / ask;
  // If API already gives spread%:
  const sp = safeNum(c?.spread_pct ?? null);
  return sp;
}
function dedupeBySymbol(list) {
  const out = [];
  const seen = new Set();
  for (const x of list) {
    const sym = x?.symbol || x?.contract_symbol;
    if (!sym) continue;
    if (seen.has(sym)) continue;
    seen.add(sym);
    out.push(x);
  }
  return out;
}

// --- INPUTS ---
const cur = unwrapItem($json || {});
const intent =
  (isPlainObject(cur.option_intent) ? cur.option_intent :
   isPlainObject(cur.optionIntent) ? cur.optionIntent :
   {}) || {};

const forced = intent.force_right === true;

const intentRight = normRight(intent.right);
const derivedRight = normRight(cur.derived_right) || normRight(cur.option_right) || null;

// OPTION A: prefer intentRight first; NO default to CALL
let desiredRight =
  (forced && intentRight) ? intentRight :
  (intentRight || derivedRight || null);

if (!desiredRight) {
  return {
    ...cur,
    option_intent: intent,
    desired_option_right: null,
    candidate_side: null,
    candidates_narrowed: [],
    option_contract_symbol: null,
    snapshots_symbols: "",
    candidate_pass: false,
    candidate_score: 1e9,
    candidate_reasons: ["missing_desired_right"],
    shortlist_debug: { reason: "No intent.right or derived_right; not defaulting to CALL." },
    error: null,
  };
}

// Expiry window
const expGte = intent.exp_gte || null;
const expLte = intent.exp_lte || null;

const all = Array.isArray(cur.contracts) ? cur.contracts :
            Array.isArray(cur.option_contracts) ? cur.option_contracts :
            Array.isArray(cur.contracts_raw) ? cur.contracts_raw :
            [];

// Filter by right + expiry
let pool = all.filter(c => {
  const r = getRight(c);

  if (forced) {
    // forced: require known match
    if (r !== desiredRight) return false;
  } else {
    // not forced: enforce if known, allow unknown
    if (r && r !== desiredRight) return false;
  }

  const exp = getExp(c);
  if (expGte && exp && exp < expGte) return false;
  if (expLte && exp && exp > expLte) return false;

  return true;
});

// earliest expiry in pool
const exps = pool.map(getExp).filter(Boolean).sort();
const minExpiry = exps.length ? exps[0] : null;

// Optional: earliest expiry + 1 day protection is handled later in your workflow;
// shortlist keeps earliest expiry; downstream logic/safety can bump it.

// Narrow to earliest expiry (if known)
if (minExpiry) pool = pool.filter(c => getExp(c) === minExpiry);

// Additional filters
const minOi = safeNum(intent.min_oi) ?? 0;
pool = pool.filter(c => getOi(c) >= minOi);

// Spread filter (if spread can be computed)
const maxSpreadPct = safeNum(intent.max_spread_pct);
if (maxSpreadPct != null) {
  pool = pool.filter(c => {
    const sp = getSpreadPct(c);
    if (sp == null) return true; // allow unknown here; Liquid node will gate strictly using snapshots
    return sp <= maxSpreadPct;
  });
}

// Prefer near-ATM by strike distance if we have underlying price hint
const underlyingPx =
  safeNum(cur?.underlying_last) ??
  safeNum(cur?.underlying_price) ??
  safeNum(cur?.price?.last_close) ??
  null;

function score(c) {
  const strike = getStrike(c);
  const oi = getOi(c);
  const sp = getSpreadPct(c);

  // Lower score is better
  let s = 0;
  if (underlyingPx != null && strike != null) s += Math.abs(strike - underlyingPx);
  s += (sp != null ? sp * 100 : 2);         // prefer tighter spreads when known
  s -= Math.min(oi, 5000) / 5000;          // prefer higher OI a bit
  return s;
}

pool = dedupeBySymbol(pool);

pool.sort((a, b) => score(a) - score(b));

// keep top N for downstream snapshots (<=100 symbols total)
const keepN = 30;
const finalPool = pool.slice(0, keepN);

const selected = finalPool.length ? finalPool[0] : null;
const optionContractSymbol = selected ? (selected.symbol || selected.contract_symbol || null) : null;

// Build snapshots_symbols (<=100)
const snapshotsSymbolsArr = finalPool.map(x => x.symbol || x.contract_symbol).filter(Boolean).slice(0, 100);
const snapshots_symbols = snapshotsSymbolsArr.join(",");

const shortlist_debug = {
  desiredRight,
  forced,
  expGte,
  expLte,
  minExpiry,
  counts: {
    all: all.length,
    after_filters: pool.length,
    finalPool: finalPool.length,
  },
};

const candidate_pass = Boolean(optionContractSymbol);

return {
  ...cur,
  // keep intent stable for downstream
  option_intent: isPlainObject(cur.option_intent) ? cur.option_intent : intent,

  target_expiration: minExpiry,
  desired_option_right: desiredRight,

  shortlist_contracts: finalPool,
  candidates_narrowed: finalPool,
  selected,
  selected_expiration: selected ? getExp(selected) : null,
  option_contract_symbol: optionContractSymbol,

  snapshots_symbols,
  shortlist_debug,
  candidate_pass,
  candidate_score: candidate_pass ? 0 : 1e9,
  candidate_reasons: candidate_pass ? [] : ["no_contract_selected"],
  error: null,
};

// n8n Code node (Run Once for Each Item)
// Compute trend_direction / strength_score / confidence deterministically.
// Output fields:
// - confidence_pre (0..1)
// - confidencePct_pre (0..100)
// - trend_direction_pre, trend_strength_score_pre, trend_strength_pre, alignment_pre, adx_confirmation_pre
//
// AI will be instructed to NOT recompute confidence.

function toNum(x) {
  if (typeof x === 'number' && Number.isFinite(x)) return x;
  if (typeof x === 'string') {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function clamp(x, lo, hi) {
  if (!Number.isFinite(x)) return null;
  return Math.min(hi, Math.max(lo, x));
}

// "1m","2m","5m","15m","60m","1h","4h","1d"
function tfToMinutes(tf) {
  const s = String(tf ?? '').trim().toLowerCase();
  const m = s.match(/^(\d+)\s*(m|h|d)$/);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n) || n <= 0) return null;
  const unit = m[2];
  if (unit === 'm') return n;
  if (unit === 'h') return n * 60;
  if (unit === 'd') return n * 1440;
  return null;
}

function pickHighTf(tfs) {
  // Follow your policy: prefer 5m else 15m else 60m else slowest.
  const set = new Set(tfs);
  if (set.has('5m')) return '5m';
  if (set.has('15m')) return '15m';
  if (set.has('60m')) return '60m';

  // slowest = largest minutes
  let best = null;
  let bestMin = -1;
  for (const tf of tfs) {
    const mins = tfToMinutes(tf);
    if (mins != null && mins > bestMin) {
      bestMin = mins;
      best = tf;
    }
  }
  return best ?? (tfs[0] ?? null);
}

function normDirFromDmi(diPlus, diMinus) {
  if (diPlus == null || diMinus == null) return null;
  if (diPlus > diMinus) return 'bullish';
  if (diMinus > diPlus) return 'bearish';
  return 'flat';
}

function strengthLabel(score) {
  if (score == null) return null;
  if (score < 25) return 'weak';
  if (score < 60) return 'moderate';
  return 'strong';
}

// TD adjustment: only small. Penalize if TD direction is against trend AND setupCompleted.
function tdAdjust(intervals, trendDirection /* 'uptrend'|'downtrend'|null */) {
  if (!trendDirection) return 0;

  const want = trendDirection === 'uptrend' ? 'bullish' : 'bearish';
  const oppose = want === 'bullish' ? 'bearish' : 'bullish';

  let supports = false;
  let against = false;

  for (const tf of Object.keys(intervals || {})) {
    const dm = intervals?.[tf]?.demark;
    if (!dm) continue;

    const setupDir = (dm.setupDir ?? null);
    const countdownDir = (dm.countdownDir ?? null);

    const setupCompleted = !!dm.setupCompleted;
    const setupCount = toNum(dm.setupCount);
    const hasSetupSignal = setupCompleted || (setupCount != null && setupCount >= 9);

    const dir = setupDir || countdownDir;

    if (dir === want && hasSetupSignal) supports = true;
    if (dir === oppose && hasSetupSignal) against = true;
  }

  if (against) return -0.05;
  if (supports) return +0.03;
  return 0;
}

// ---------------- main ----------------
const payload = ($json && typeof $json === 'object') ? $json : {};
const intervals = (payload.intervals && typeof payload.intervals === 'object') ? payload.intervals : (payload.timeframes || {});
const tfKeys = Object.keys(intervals || {});

let bull = 0, bear = 0, known = 0;
let spreads = [];

for (const tf of tfKeys) {
  const dmi = intervals?.[tf]?.dmi || {};
  const diPlus = toNum(dmi.diPlus ?? dmi.di_plus ?? dmi.plus_di ?? dmi["DI+"]);
  const diMinus = toNum(dmi.diMinus ?? dmi.di_minus ?? dmi.minus_di ?? dmi["DI-"]);

  const dir = normDirFromDmi(diPlus, diMinus);
  if (dir === 'bullish') { bull++; known++; }
  else if (dir === 'bearish') { bear++; known++; }

  if (diPlus != null && diMinus != null) {
    spreads.push(Math.abs(diPlus - diMinus));
  }
}

let trend_direction_pre = null;
let alignment_pre = null;

if (known === 0) {
  trend_direction_pre = null;
  alignment_pre = null;
} else if (bull === known) {
  trend_direction_pre = 'uptrend';
  alignment_pre = 'all_aligned';
} else if (bear === known) {
  trend_direction_pre = 'downtrend';
  alignment_pre = 'all_aligned';
} else {
  trend_direction_pre = 'mixed';
  alignment_pre = 'mixed';
}

// strength score
let trend_strength_score_pre = null;
if (spreads.length > 0) {
  const avg = spreads.reduce((a,b) => a + b, 0) / spreads.length;
  trend_strength_score_pre = clamp(Math.round(avg * 5), 0, 100);
}

const trend_strength_pre = strengthLabel(trend_strength_score_pre);

// ADX confirmation (context only) using "high tf"
const highTf = pickHighTf(tfKeys);
let adx_confirmation_pre = null;
if (highTf) {
  const adx = toNum(intervals?.[highTf]?.dmi?.adx ?? intervals?.[highTf]?.dmi?.ADX);
  if (adx != null) adx_confirmation_pre = (adx > 25 ? 'confirmed' : 'not_confirmed');
}

// confidence
let conf = 0.40;
if ((trend_direction_pre === 'uptrend' || trend_direction_pre === 'downtrend') && trend_strength_score_pre != null) {
  conf = 0.45 + 0.40 * clamp(trend_strength_score_pre, 0, 100) / 100;
}
if (adx_confirmation_pre === 'confirmed') conf += 0.05;

// TD adjustment
conf += tdAdjust(intervals, (trend_direction_pre === 'mixed') ? null : trend_direction_pre);

conf = clamp(Math.round(conf * 100) / 100, 0, 1);
const confidence_pre = conf;
const confidencePct_pre = confidence_pre == null ? null : Math.round(confidence_pre * 10000) / 100; // 2dp pct

return [
  {
    json: {
      ...payload,

      // deterministic fields (preferred)
      confidence_pre,
      confidencePct_pre,
      trend_direction_pre,
      trend_strength_score_pre,
      trend_strength_pre,
      alignment_pre,
      adx_confirmation_pre,

      // debug (optional)
      confidence_debug: {
        tfKeys,
        known_count: known,
        bull_count: bull,
        bear_count: bear,
        spreads,
        highTf
      }
    }
  }
];

// n8n Code node: Compare Candidates
// MODE: Run Once for All Items
//
// Purpose:
// - Accept both CALL and PUT candidate items.
// - Deterministically choose a winner (CALL vs PUT) and attach the other as `other_candidate`.
// - Keep the winner item as the main payload so downstream nodes (liquidity gating, telegram, AI) stay compatible.
// - Prevent "Winner: CALL | Other: N/A" when both sides exist.
// - Ensure option_liquidity_reason/spread/quote fields remain consistent with the winner.
//
// Output (single item):
//   - winner_side: "CALL" | "PUT" | null
//   - other_candidate: object|null (subset of the losing candidate)

function isPlainObject(x) {
  return x != null && typeof x === "object" && !Array.isArray(x);
}

function safeStr(x) {
  if (x == null) return null;
  const s = String(x).trim();
  return s === "" ? null : s;
}

function toNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string" && x.trim() !== "") {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function toInt(x) {
  const n = toNum(x);
  return n == null ? null : Math.trunc(n);
}

function normSide(v) {
  const s = safeStr(v);
  if (!s) return null;
  const t = s.toUpperCase();
  if (t === "CALL" || t === "C") return "CALL";
  if (t === "PUT" || t === "P") return "PUT";
  return null;
}

function inferDesiredSide(base) {
  const explicit =
    normSide(base?.winner_side) ??
    normSide(base?.desired_option_right) ??
    normSide(base?.option_intent?.right);

  if (explicit) return explicit;

  const bias = safeStr(base?.technical_bias)?.toLowerCase();
  const td = safeStr(base?.trend_direction)?.toLowerCase();

  if (bias === "bearish" || td === "downtrend") return "PUT";
  if (bias === "bullish" || td === "uptrend") return "CALL";
  return null;
}

function pickSubset(c) {
  // Keep this small but sufficient for Telegram + debugging
  return {
    ticker: c?.ticker ?? null,
    overall_timeframe: c?.overall_timeframe ?? c?.timeframes ?? null,
    candidate_side: normSide(c?.candidate_side) ?? null,
    candidate_pass: (c?.candidate_pass === true || c?.candidate_pass === false) ? c.candidate_pass : null,

    option_contract_symbol: safeStr(c?.option_contract_symbol),
    option_bid: toNum(c?.option_bid),
    option_ask: toNum(c?.option_ask),
    option_mid: toNum(c?.option_mid),
    option_spread_pct: toNum(c?.option_spread_pct),
    option_entry_premium: toNum(c?.option_entry_premium),

    option_risk_reward: toNum(c?.option_risk_reward),
    option_delta: toNum(c?.option_delta),

    option_liquidity_ok: (c?.option_liquidity_ok === true || c?.option_liquidity_ok === false) ? c.option_liquidity_ok : null,
    option_liquidity_reason: safeStr(c?.option_liquidity_reason),

    // Keep a few level fields if present
    trigger_price: toNum(c?.trigger_price),
    invalidation_level: toNum(c?.invalidation_level),
    target_level: toNum(c?.target_level),
  };
}

function scoreCandidate(c, desiredSide) {
  const side = normSide(c?.candidate_side) ?? normSide(c?.option_intent?.right) ?? null;

  const passOk = c?.candidate_pass === true ? 1 : 0;
  const liqOk = c?.option_liquidity_ok === true ? 1 : 0;

  const sideMatch = (desiredSide && side && side === desiredSide) ? 1 : 0;

  const rr = toNum(c?.option_risk_reward);
  const rrScore = rr == null ? Number.NEGATIVE_INFINITY : rr;

  const sp = toNum(c?.option_spread_pct);
  const spScore = sp == null ? Number.POSITIVE_INFINITY : sp; // lower is better

  const oi =
    toInt(c?.selected?.open_interest) ??
    toInt(c?.open_interest) ??
    toInt(c?.selected?.oi) ??
    null;
  const oiScore = oi == null ? -1 : oi;

  // Lexicographic priority:
  // 1) candidate_pass
  // 2) option_liquidity_ok
  // 3) side match with desired
  // 4) higher RR
  // 5) lower spread
  // 6) higher OI
  return { passOk, liqOk, sideMatch, rrScore, spScore, oiScore, side };
}

function better(a, b) {
  // return true if a is better than b
  const keys = ["passOk","liqOk","sideMatch","rrScore","spScore","oiScore"];
  for (const k of keys) {
    if (a[k] === b[k]) continue;
    if (k === "spScore") return a[k] < b[k];      // lower spread is better
    return a[k] > b[k];                           // higher is better
  }
  return false;
}

// ---- main ----
const items = $input.all();
const candidates = items.map(i => i?.json).filter(isPlainObject);

if (candidates.length === 0) {
  return [{
    json: {
      candidate_pass: false,
      winner_side: null,
      other_candidate: null,
      error: "no_candidates"
    }
  }];
}

// Separate by side if both exist
const bySide = { CALL: null, PUT: null };
for (const c of candidates) {
  const side = normSide(c?.candidate_side) ?? normSide(c?.option_intent?.right);
  if (!side) continue;
  // Keep the "best" per side in case duplicates exist
  if (!bySide[side]) {
    bySide[side] = c;
  } else {
    const desired = inferDesiredSide(c) ?? inferDesiredSide(bySide[side]) ?? null;
    const s1 = scoreCandidate(c, desired);
    const s2 = scoreCandidate(bySide[side], desired);
    if (better(s1, s2)) bySide[side] = c;
  }
}

// If only one side exists, winner is that side
let left = bySide.CALL || null;
let right = bySide.PUT || null;

// If neither side was labeled, fall back to first candidate as winner
if (!left && !right) {
  const winner = candidates[0];
  const out = { ...winner };
  out.winner_side = normSide(out?.candidate_side) ?? null;
  out.other_candidate = null;
  out.candidate_compare = {
    desired_side: inferDesiredSide(out),
    candidates_seen: candidates.length,
    sides_seen: candidates.map(c => normSide(c?.candidate_side) ?? null).filter(Boolean),
    reason: "no_side_labels_fell_back_to_first"
  };
  return [{ json: out }];
}

const base = (left || right);
const desiredSide = inferDesiredSide(base);

// If only one side is present
if (!left || !right) {
  const winner = left || right;
  const out = { ...winner };
  out.winner_side = normSide(winner?.candidate_side) ?? (left ? "CALL" : "PUT");
  out.other_candidate = null;
  out.candidate_compare = {
    desired_side: desiredSide,
    candidates_seen: candidates.length,
    sides_seen: Object.entries(bySide).filter(([k,v])=>!!v).map(([k])=>k),
    winner_side: out.winner_side,
    other_side: null,
    reason: "single_side_available"
  };
  return [{ json: out }];
}

// Both sides exist — compute deterministic winner
const sCall = scoreCandidate(left, desiredSide);
const sPut  = scoreCandidate(right, desiredSide);

let winner = left;
let loser  = right;
let reason = "score_call_ge_put";

if (better(sPut, sCall)) {
  winner = right;
  loser  = left;
  reason = "score_put_gt_call";
}

// Build output = winner as main payload
const out = { ...winner };
out.winner_side = normSide(winner?.candidate_side) ?? null;
out.other_candidate = pickSubset(loser);

// Ensure the winner's own liquidity fields stay on the main payload
// (prevents reason/spread mismatches in Telegram)
out.option_liquidity_ok = (winner?.option_liquidity_ok === true || winner?.option_liquidity_ok === false) ? winner.option_liquidity_ok : out.option_liquidity_ok;
out.option_liquidity_reason = safeStr(winner?.option_liquidity_reason) ?? out.option_liquidity_reason ?? null;

// Candidate compare diagnostics (small)
out.candidate_compare = {
  desired_side: desiredSide,
  winner_side: out.winner_side,
  other_side: normSide(loser?.candidate_side) ?? null,
  reason,
  call: pickSubset(left),
  put: pickSubset(right),
};

return [{ json: out }];

// Code node: Enforce Desired Right + Slim Payload (before AI)
// MODE: Run Once for Each Item
//
// Goal: reduce tokens sent into AI node by keeping only fields required by system schema/rules.

function normRight(v) {
  if (!v) return null;
  const s = String(v).trim().toLowerCase();
  if (s === "call" || s === "c") return "call";
  if (s === "put" || s === "p") return "put";
  return null;
}

function pick(obj, keys) {
  const out = {};
  for (const k of keys) {
    if (obj && Object.prototype.hasOwnProperty.call(obj, k)) out[k] = obj[k];
  }
  return out;
}

function isObj(x) {
  return x != null && typeof x === "object" && !Array.isArray(x);
}

// 1) Compute desired right from winner, fallback to existing desired_option_right
const winnerRight =
  normRight($json.winner_right) ||
  (String($json.winner_side || "").toUpperCase() === "CALL" ? "call" :
   String($json.winner_side || "").toUpperCase() === "PUT" ? "put" : null);

const desiredRight = winnerRight || normRight($json.desired_option_right) || (() => {
  // If Compare Candidates hasn't set desired right yet, infer from deterministic trend/bias or DMI alignment.
  const td = String($json.trend_direction_pre || $json.trend_direction || "").toLowerCase();
  const tb = String($json.technical_bias || "").toLowerCase();
  if (td.includes("down")) return "put";
  if (td.includes("up")) return "call";
  if (tb === "bearish") return "put";
  if (tb === "bullish") return "call";

  const intervals = isObj($json.intervals) ? $json.intervals : null;
  if (!intervals) return null;

  let bull = 0;
  let bear = 0;
  for (const tf of Object.keys(intervals)) {
    const dmi = intervals?.[tf]?.dmi;
    const diPlus = Number.isFinite(+dmi?.diPlus) ? +dmi.diPlus : null;
    const diMinus = Number.isFinite(+dmi?.diMinus) ? +dmi.diMinus : null;
    if (diPlus == null || diMinus == null) continue;
    if (diMinus > diPlus) bear += 1;
    else if (diPlus > diMinus) bull += 1;
  }
  if (bear > bull && bear > 0) return "put";
  if (bull > bear && bull > 0) return "call";
  return null;
})() || null;

// 2) Minimize intervals payload (keep only what prompt uses)
const intervalsIn = isObj($json.intervals) ? $json.intervals : {};
const keepTFs = ["5m", "3m", "2m", "1m"];
const intervalsOut = {};

for (const tf of keepTFs) {
  const tfObj = intervalsIn[tf];
  if (!isObj(tfObj)) continue;

  const dmiIn = isObj(tfObj.dmi) ? tfObj.dmi : null;
  const demarkIn = isObj(tfObj.demark) ? tfObj.demark : null;
  const priceIn = isObj(tfObj.price) ? tfObj.price : null;

  intervalsOut[tf] = {
    dmi: dmiIn
      ? pick(dmiIn, ["diPlus", "diMinus", "adx"]) // drop "td" to save tokens (prompt says demark is separate)
      : { diPlus: null, diMinus: null, adx: null },
    demark: demarkIn ?? null,
    price: priceIn
      ? pick(priceIn, [
          "last_close",
          "last_high",
          "last_low",
          "swing_high_n",
          "swing_low_n",
          "atr_n_sma",
          "true_range_avg_n"
        ])
      : null
  };
}

// 3) Keep only the needed optionContext subfields
let optionContextOut = null;
if (isObj($json.optionContext)) {
  const oc = $json.optionContext;
  optionContextOut = {
    contract: isObj(oc.contract) ? pick(oc.contract, ["symbol", "right", "expiration", "strike"]) : null,
    quote: isObj(oc.quote) ? pick(oc.quote, ["bid", "ask", "mid", "spread_pct"]) : null,
    greeks: isObj(oc.greeks) ? pick(oc.greeks, ["delta", "gamma", "theta", "vega", "iv"]) : null
    // trade dropped (not required by schema/rules); add back if you truly need it
  };
}

// 4) max_spread_pct: keep as top-level scalar (avoid shipping whole option_intent)
const maxSpreadPct =
  (isObj($json.option_intent) && typeof $json.option_intent.max_spread_pct === "number")
    ? $json.option_intent.max_spread_pct
    : (typeof $json.max_spread_pct === "number" ? $json.max_spread_pct : null);

// 5) Build slim payload
const out = {
  ticker: $json.ticker ?? null,
  overall_timeframe: $json.overall_timeframe ?? null,

  intervals: intervalsOut,

  // underlying levels
  trigger_price: $json.trigger_price ?? null,
  invalidation_level: $json.invalidation_level ?? null,
  target_level: $json.target_level ?? null,

  // gates
  time_gate_ok: $json.time_gate_ok ?? null,
  time_gate_reason: $json.time_gate_reason ?? null,
  option_liquidity_ok: $json.option_liquidity_ok ?? null,
  option_liquidity_reason: $json.option_liquidity_reason ?? null,

  // trend/confidence (authoritative)
  confidence_pre: $json.confidence_pre ?? null,
  confidencePct_pre: $json.confidencePct_pre ?? null,
  trend_direction_pre: $json.trend_direction_pre ?? null,
  trend_strength_pre: $json.trend_strength_pre ?? null,
  trend_strength_score_pre: $json.trend_strength_score_pre ?? null,
  alignment_pre: $json.alignment_pre ?? null,
  adx_confirmation_pre: $json.adx_confirmation_pre ?? null,

  // option side + contract + pricing
  desired_option_right: desiredRight,
  option_right: $json.option_right ?? desiredRight ?? null, // small helper for your prompt’s fallback chain
  option_contract_symbol: $json.option_contract_symbol ?? null,

  // quote + greeks
  optionContext: optionContextOut,

  // premiums / RR (copy-through)
  option_entry_premium: $json.option_entry_premium ?? null,
  option_stop_premium: $json.option_stop_premium ?? null,
  option_take_profit_premium: $json.option_take_profit_premium ?? null,
  option_risk_reward: $json.option_risk_reward ?? null,

  // spread limit scalar
  max_spread_pct: maxSpreadPct
};

return { json: out };

// Code node: Compute Option Metrics (Gamma scalp helper)
// MODE: Run Once for Each Item
// Adds intrinsic/extrinsic/theta% and simple expected-move.
// Expects optionContext from Enrich Payload for AI.

function n(x) {
  const v = (typeof x === 'string') ? Number.parseFloat(x) : x;
  return (typeof v === 'number' && Number.isFinite(v)) ? v : null;
}
function clamp(x, lo, hi) { return Math.max(lo, Math.min(hi, x)); }

const j = ($json && typeof $json === 'object') ? $json : {};
const oc = j.optionContext || {};
const c = oc.contract || {};
const q = oc.quote || {};
const g = oc.greeks || {};

const right = (c.right || '').toString().toLowerCase();
const strike = n(c.strike);
const mid = n(q.mid) ?? n(j.option_mid) ?? n(j.option_entry_premium);

const underlying =
  n(j.underlying_last) ??
  n(j.underlying_price) ??
  n(j.trigger_price) ??
  n(j?.intervals?.['60m']?.price?.last_close) ??
  n(j?.intervals?.['15m']?.price?.last_close) ??
  n(j?.intervals?.['1m']?.price?.last_close) ??
  null;

// DTE (calendar days)
let dte_days = null;
if (c.expiration) {
  const exp = new Date(String(c.expiration).slice(0, 10) + "T00:00:00Z").getTime();
  const now = Date.now();
  if (Number.isFinite(exp)) {
    dte_days = Math.max(0, Math.round((exp - now) / (24*60*60*1000)));
  }
}

let intrinsic = null;
let extrinsic = null;
let extrinsic_pct = null;

if (underlying != null && strike != null && mid != null) {
  if (right === 'call') intrinsic = Math.max(0, underlying - strike);
  else if (right === 'put') intrinsic = Math.max(0, strike - underlying);

  extrinsic = mid - (intrinsic ?? 0);
  extrinsic_pct = (mid > 0) ? clamp(extrinsic / mid, -5, 5) : null;
}

const delta = n(g.delta);
const gamma = n(g.gamma);
const theta = n(g.theta);
const vega  = n(g.vega);
const iv    = n(g.iv);

// theta “cost” as % of premium per day
const theta_pct_per_day = (mid != null && mid > 0 && theta != null)
  ? clamp((-theta) / mid, -5, 5)
  : null;

// simple expected move to expiry from IV (calendar)
const expected_move_to_exp = (underlying != null && iv != null && dte_days != null)
  ? underlying * iv * Math.sqrt(Math.max(dte_days, 1) / 365)
  : null;

return {
  json: {
    ...j,
    optionMetrics: {
      underlying,
      right: right || null,
      strike,
      mid,
      dte_days,
      intrinsic,
      extrinsic,
      extrinsic_pct,
      delta,
      gamma,
      theta,
      theta_pct_per_day,
      vega,
      iv,
      expected_move_to_exp,
    }
  }
};

// Code node: Compute Option ATR Stops/TP (Gamma scalp)
// MODE: Run Once for Each Item
// Merges option bars response back into the enriched payload and computes ATR-based stop/TP.
//
// Assumes upstream node name: "Compute Option Metrics"
// Assumes current $json is the response from Get Option Bars (likely { bars: {SYM:[...]} } )

function n(x) {
  const v = (typeof x === 'string') ? Number.parseFloat(x) : x;
  return (typeof v === 'number' && Number.isFinite(v)) ? v : null;
}
function round2(x){ return (x == null) ? null : Math.round(x * 100) / 100; }

// Pull full payload from Compute Option Metrics (to preserve context)
const base = ($items("Compute Option Metrics")?.[0]?.json && typeof $items("Compute Option Metrics")[0].json === "object")
  ? $items("Compute Option Metrics")[0].json
  : (typeof $json === "object" ? $json : {});

const resp = (typeof $json === "object" && $json) ? $json : {};

const sym = (base.option_contract_symbol || base?.optionContext?.contract?.symbol || '').toString().toUpperCase();

// Get bars map
const barsMap = resp?.bars ?? resp?.data?.bars ?? resp?.optionBars ?? resp ?? null;

// Extract bars array
const bars = (barsMap && sym && Array.isArray(barsMap[sym])) ? barsMap[sym]
  : (Array.isArray(resp?.bars) ? resp.bars : null);

if (!Array.isArray(bars) || bars.length < 15) {
  return {
    json: {
      ...base,
      optionStops: {
        reason: "Not enough option bars to compute ATR",
        atr: null,
        entry: base?.option_mid ?? base?.option_entry_premium ?? null,
        stop: null,
        tp: null,
        rr: null
      }
    }
  };
}

// ATR (simple average TR) over last N bars
const N = Math.min(14, bars.length - 1);
let trs = [];
for (let i = bars.length - N; i < bars.length; i++) {
  const cur = bars[i];
  const prev = bars[i - 1];
  const h = n(cur.h), l = n(cur.l), pc = n(prev.c);
  if (h == null || l == null || pc == null) continue;
  const tr = Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
  trs.push(tr);
}
const atr = trs.length ? (trs.reduce((a,b)=>a+b,0) / trs.length) : null;

// Entry from current quote mid if available; else last close
const entry =
  n(base?.optionContext?.quote?.mid) ??
  n(base?.option_mid) ??
  n(base?.option_entry_premium) ??
  n(bars[bars.length - 1]?.c) ??
  null;

if (atr == null || entry == null) {
  return {
    json: {
      ...base,
      optionStops: {
        reason: "Missing ATR or entry",
        atr: round2(atr),
        entry: round2(entry),
        stop: null,
        tp: null,
        rr: null
      }
    }
  };
}

// Gamma scalp multipliers
const STOP_ATR = 0.8;
const TP_ATR   = 1.6;

const stop = Math.max(0.01, entry - STOP_ATR * atr);
const tp   = entry + TP_ATR * atr;

const risk = entry - stop;
const reward = tp - entry;
const rr = (risk > 0) ? (reward / risk) : null;

// Clean bars out of payload to keep tokens down; keep a tiny summary
const bars_summary = {
  symbol: sym || null,
  timeframe: "1Min",
  bars_used: bars.length,
  last_bar_time: bars[bars.length - 1]?.t ?? null
};

return {
  json: {
    ...base,
    option_entry_premium: round2(entry),
    option_stop_premium: round2(stop),
    option_take_profit_premium: round2(tp),
    option_risk_reward: (rr == null) ? null : Number(rr.toFixed(2)),
    optionStops: {
      atr: round2(atr),
      stop_atr: STOP_ATR,
      tp_atr: TP_ATR,
      bars_summary
    }
  }
};

// n8n Code node: Compute Synthetic Option Stops/TP (Delta-Gamma)
// MODE: Run Once for Each Item
//
// Requires from upstream payload (your "Compute Option Metrics" output typically has these):
// - trigger_price, invalidation_level, target_level  (underlying levels)
// - option_bid / option_ask / option_mid
// - option_delta, option_gamma (or optionMetrics.delta/gamma)
//
// Produces: option_entry_premium, option_stop_premium, option_take_profit_premium, option_risk_reward

function n(x) {
  const v = (typeof x === 'string') ? Number.parseFloat(x) : x;
  return (typeof v === 'number' && Number.isFinite(v)) ? v : null;
}
function round2(x){ return (x == null) ? null : Math.round(x * 100) / 100; }

const base = ($json && typeof $json === 'object') ? $json : {};

const S0   = n(base.trigger_price) ?? n(base.underlying_last) ?? n(base?.optionMetrics?.underlying) ?? null;
const Sinv = n(base.invalidation_level);
const Stgt = n(base.target_level);

const bid = n(base.option_bid);
const ask = n(base.option_ask);
const mid = n(base.option_mid) ?? (bid != null && ask != null ? (bid + ask) / 2 : null);

// Use ask as entry for long option (more conservative)
const entry = (ask != null) ? ask : mid;

const delta = n(base.option_delta) ?? n(base?.optionMetrics?.delta);
const gamma = n(base.option_gamma) ?? n(base?.optionMetrics?.gamma);

// Helper: delta-gamma approximation around current price
function approxPremiumAt(S) {
  if (entry == null || S0 == null || S == null || delta == null) return null;
  const dS = S - S0;
  const gTerm = (gamma != null) ? (0.5 * gamma * dS * dS) : 0;
  return entry + (delta * dS) + gTerm;
}

let stop = approxPremiumAt(Sinv);
let tp   = approxPremiumAt(Stgt);

// Basic sanity clamps for a long premium trade:
if (entry != null && stop != null) stop = Math.min(stop, entry - 0.01);
if (entry != null && tp   != null) tp   = Math.max(tp,   entry + 0.01);

if (stop != null) stop = Math.max(0.01, stop);
if (tp   != null) tp   = Math.max(0.01, tp);

let rr = null;
if (entry != null && stop != null && tp != null) {
  const risk = entry - stop;
  const reward = tp - entry;
  rr = (risk > 0) ? (reward / risk) : null;
}

return [{
  json: {
    ...base,
    option_entry_premium: round2(entry),
    option_stop_premium: round2(stop),
    option_take_profit_premium: round2(tp),
    option_risk_reward: (rr == null) ? null : Number(rr.toFixed(2)),
    optionStops: {
      method: "delta_gamma_from_underlying_levels",
      S0, Sinv, Stgt,
      delta, gamma
    }
  }
}];

// n8n Code node: Render Verification JSON -> Telegram
// MODE: Run Once for Each Item
//
// Input can be either:
//  A) $json is already the verification object: { verdict, severity, summary, ... }
//  B) $json.output (or verification_output/report) is a JSON string containing that object
//
// Output:
// - telegram_text (string) ready for Telegram Send Message node
// - preserves original fields by passing through

function isPlainObject(x) {
  return x != null && typeof x === "object" && !Array.isArray(x);
}

function safeNum(x) {
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string") {
    const n = Number.parseFloat(x);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function fmtNum(x, digits = 2) {
  const n = safeNum(x);
  if (n == null) return "n/a";
  return n.toFixed(digits);
}

function pct(x, digits = 1) {
  const n = safeNum(x);
  if (n == null) return "n/a";
  return (n * 100).toFixed(digits) + "%";
}

function fmtBool(x) {
  if (x === true) return "✅";
  if (x === false) return "❌";
  return "n/a";
}

function fmtRight(r) {
  if (!r) return "n/a";
  const s = String(r).toLowerCase();
  if (s === "call") return "CALL";
  if (s === "put") return "PUT";
  return s.toUpperCase();
}

function verdictEmoji(verdict, severity) {
  const v = (verdict || "").toUpperCase();
  const s = (severity || "").toLowerCase();

  if (v === "ERROR") return "🛑";
  if (v === "MISMATCH") return "⚠️";
  if (v === "WAIT") return "🟡";
  if (v === "OK") {
    if (s === "warning") return "🟠";
    if (s === "critical") return "🔴";
    return "🟢";
  }
  return "ℹ️";
}

function pick(obj, path, fallback = null) {
  try {
    const parts = path.split(".");
    let cur = obj;
    for (const p of parts) {
      if (!isPlainObject(cur) && !Array.isArray(cur)) return fallback;
      cur = cur[p];
      if (cur === undefined) return fallback;
    }
    return cur == null ? fallback : cur;
  } catch {
    return fallback;
  }
}

function clampIssues(arr) {
  if (!Array.isArray(arr)) return [];
  return arr.filter(Boolean).slice(0, 8); // keep message short
}

function clampRecs(arr) {
  if (!Array.isArray(arr)) return [];
  return arr.filter(Boolean).slice(0, 6);
}

function stripCodeFences(s) {
  if (typeof s !== "string") return s;
  let t = s.trim();
  t = t.replace(/^```(?:json)?\s*/i, "");
  t = t.replace(/\s*```$/i, "");
  return t.trim();
}

// Parse JSON safely; if parse fails, try extracting minimal fields with regex.
function parseMaybeJson(raw) {
  if (raw == null) return null;
  if (isPlainObject(raw)) return raw;

  if (typeof raw === "string") {
    const t = stripCodeFences(raw);
    try {
      const obj = JSON.parse(t);
      return isPlainObject(obj) ? obj : null;
    } catch {
      // fallback: try to extract just verdict/severity minimally
      const verdict = (t.match(/"verdict"\s*:\s*"([^"]+)"/i) || [])[1] || null;
      const severity = (t.match(/"severity"\s*:\s*"([^"]+)"/i) || [])[1] || null;
      if (verdict || severity) return { verdict, severity };
      return null;
    }
  }
  return null;
}

// --- Resolve the actual verification object ---
const root = isPlainObject($json) ? $json : {};
const raw =
  root.output ??
  root.verification_output ??
  root.report ??
  null;

// If $json itself already looks like a report, prefer it; else parse the nested raw.
let data = null;
if (root && (root.verdict || root.summary || root.computed || root.consistency)) {
  data = root;
} else {
  data = parseMaybeJson(raw) || {};
}

// --- Pull fields ---
const verdict = pick(data, "verdict", null);
const severity = pick(data, "severity", null);

const ticker = pick(data, "summary.ticker", null);
const tfs = pick(data, "summary.timeframes", null);
const bias = pick(data, "summary.technical_bias", null);
const trendDir = pick(data, "summary.trend_direction", null);
const conf = safeNum(pick(data, "summary.confidence", null));
const selRight = pick(data, "summary.selected_option_right", null);
const selContract = pick(data, "summary.selected_contract", null);
const decision = pick(data, "summary.decision", null);

const rr = safeNum(pick(data, "computed.underlying_rr", null));
const risk = safeNum(pick(data, "computed.underlying_risk", null));
const reward = safeNum(pick(data, "computed.underlying_reward", null));

const c_biasRight = pick(data, "consistency.bias_vs_selected_right_ok", null);
const c_gates = pick(data, "consistency.gates_respected_ok", null);
const c_rr = pick(data, "consistency.rr_threshold_respected_ok", null);
const c_both = pick(data, "consistency.candidate_compare_has_both_sides", null);

const issues = clampIssues(pick(data, "issues", []));
const recs = clampRecs(pick(data, "recommendations", []));

const prefRight = pick(data, "suggested_corrections.preferred_option_right", null);
const sugWinRight = pick(data, "suggested_corrections.suggested_winner_right", null);
const corrReason = pick(data, "suggested_corrections.reason", null);

// --- Render (Telegram-friendly) ---
const lines = [];

lines.push(`${verdictEmoji(verdict, severity)} Verification: ${verdict || "n/a"} (${severity || "n/a"})`);

if (ticker || tfs) {
  lines.push(`Ticker: ${ticker || "n/a"} | TF: ${tfs || "n/a"}`);
}

lines.push(
  `Bias: ${bias ? String(bias).toUpperCase() : "n/a"} | Trend: ${trendDir || "n/a"} | Conf: ${conf == null ? "n/a" : pct(conf, 0)}`
);

lines.push(
  `Decision: ${decision || "n/a"} | Selected: ${fmtRight(selRight)} | Contract: ${selContract || "n/a"}`
);

lines.push(
  `Underlying R:R: ${rr == null ? "n/a" : fmtNum(rr, 2)} (risk ${risk == null ? "n/a" : fmtNum(risk, 2)}, reward ${reward == null ? "n/a" : fmtNum(reward, 2)})`
);

lines.push("");
lines.push("Consistency:");
lines.push(`• Bias vs Selected Right: ${fmtBool(c_biasRight)}`);
lines.push(`• Gates Respected: ${fmtBool(c_gates)}`);
lines.push(`• RR Threshold Respected: ${fmtBool(c_rr)}`);
lines.push(`• Both Sides Present: ${fmtBool(c_both)}`);

// Issues
if (issues.length) {
  lines.push("");
  lines.push(`Issues (${issues.length}):`);
  for (const it of issues) {
    const code = it?.code ? String(it.code) : "UNKNOWN";
    const sev = it?.severity ? String(it.severity) : "info";
    const msg = it?.message ? String(it.message) : "";
    const icon = sev === "critical" ? "🛑" : sev === "warning" ? "⚠️" : "ℹ️";
    const clipped = msg.length > 170 ? msg.slice(0, 167) + "…" : msg;
    lines.push(`• ${icon} ${code}: ${clipped}`);
  }
}

// Suggested corrections
if (prefRight || sugWinRight || corrReason) {
  lines.push("");
  lines.push("Suggested corrections:");
  if (prefRight) lines.push(`• Preferred Right: ${fmtRight(prefRight)}`);
  if (sugWinRight) lines.push(`• Suggested Winner: ${fmtRight(sugWinRight)}`);
  if (corrReason) {
    const cr = String(corrReason);
    const clipped = cr.length > 220 ? cr.slice(0, 217) + "…" : cr;
    lines.push(`• Reason: ${clipped}`);
  }
}

// Recommendations
if (recs.length) {
  lines.push("");
  lines.push(`Recommendations (${recs.length}):`);
  for (const r of recs) {
    const action = r?.action ? String(r.action) : "Action";
    const why = r?.why ? String(r.why) : "";
    const where = r?.where ? String(r.where) : null;

    let line = `• ${action}`;
    if (where) line += ` (@${where})`;
    if (why) {
      const clipped = why.length > 180 ? why.slice(0, 177) + "…" : why;
      line += ` — ${clipped}`;
    }
    lines.push(line);
  }
}

// Final telegram text (avoid huge messages)
let telegram_text = lines.join("\n").trim();
if (telegram_text.length > 3500) {
  telegram_text = telegram_text.slice(0, 3490) + "\n…(truncated)";
}

return {
  json: {
    ...root,          // preserve original wrapper fields (e.g., output string)
    ...data,          // also expose parsed fields at top-level for downstream nodes
    telegram_text,
  },
};

// n8n Code node: Parse AI Agent Output -> JSON
// MODE: Run Once for Each Item
//
// Input:  $json.output is a STRING that contains JSON (sometimes wrapped in ```json fences)
// Output: $json.output becomes an OBJECT, and also sets:
//   - output_text (original string)
//   - output_parse_ok (boolean)
//   - output_parse_error (string|null)

function stripCodeFences(s) {
  if (typeof s !== 'string') return s;
  return s
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function tryParseJsonString(s) {
  const t = stripCodeFences(s);

  // 1) normal JSON.parse
  try {
    return { ok: true, value: JSON.parse(t), error: null };
  } catch (e1) {}

  // 2) fallback: extract first {...} block
  try {
    const start = t.indexOf('{');
    const end = t.lastIndexOf('}');
    if (start >= 0 && end > start) {
      const slice = t.slice(start, end + 1);
      return { ok: true, value: JSON.parse(slice), error: null };
    }
  } catch (e2) {}

  // 3) last resort: regex pull verdict so IF can still work
  const m = t.match(/"verdict"\s*:\s*"([^"]+)"/i);
  if (m) {
    return { ok: true, value: { verdict: m[1] }, error: null };
  }

  return { ok: false, value: null, error: 'Unable to parse AI output as JSON' };
}

const raw = $json.output;

// Preserve original text for debugging
const out = {
  ...$json,
  output_text: typeof raw === 'string' ? raw : JSON.stringify(raw),
  output_parse_ok: false,
  output_parse_error: null,
};

if (raw != null && typeof raw === 'object' && !Array.isArray(raw)) {
  // already parsed
  out.output = raw;
  out.output_parse_ok = true;
} else if (typeof raw === 'string') {
  const parsed = tryParseJsonString(raw);
  out.output = parsed.ok ? parsed.value : { verdict: null };
  out.output_parse_ok = parsed.ok;
  out.output_parse_error = parsed.ok ? null : parsed.error;
} else {
  out.output = { verdict: null };
  out.output_parse_ok = false;
  out.output_parse_error = 'output is missing or not a string/object';
}

return { json: out };
